INSERT INTO `entry` VALUES ('222', '76', '实拍东德男子冒死翻越柏林墙全程[组图] (1/16) 2014-1-30 20:05 阅读(0)', '<p>\r\n	&nbsp;</p>\r\n<table cellpadding=\"0\" cellspacing=\"0\" id=\"blogContentTable\" style=\"position: relative; padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px; padding-left: 0px; border-spacing: 0px; width: 880px; padding-right: 0px; border-collapse: collapse; font: 12px/19px punctuation, 微软雅黑, Tohoma; white-space: normal; table-layout: fixed; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<tbody style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n		<tr style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n			<td style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; word-wrap: break-word; padding-top: 0px\" valign=\"top\">\r\n				<div id=\"blogContainer\" style=\"position: relative; padding-bottom: 0px; margin: 0px; padding-left: 16px; padding-right: 16px; height: 4200px; overflow: hidden; padding-top: 0px\">\r\n					<div align=\"center\" class=\"lp_title_type_3\" id=\"paperTitleArea\" style=\"background-image: url(/qzone/space_item/orig/9/81177_t5.gif); padding-bottom: 0px; margin: 0px 0px 35px 72px; padding-left: 0px; width: 690px; padding-right: 0px; background-repeat: no-repeat; background-position: 50% 50%; height: 70px; padding-top: 0px\">\r\n						<span id=\"paperTitle\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; display: block; color: rgb(0,0,0); word-break: break-all; padding-top: 25px\"><font color=\"#000000\" face=\"微软雅黑\" style=\"font-size: 26px\">实拍东德男子冒死翻越柏林墙全程[组图] (1/16)</font></span></div>\r\n					<div data-webp-ctx-e=\"1\" id=\"blogDetailDiv\" style=\"padding-bottom: 0px; margin: 0px; min-height: 380px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); font-size: 14px; padding-top: 0px\">\r\n						<div class=\"blog_details_20120222\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n							<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n								<a href=\"http://news.ifeng.com/history/vp/detail_2011_11/11/10580793_6.shtml\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\">http://news.ifeng.com/history/vp/detail_2011_11/11/10580793_6.shtml</a>&nbsp;<br />\r\n								<br />\r\n								<br />\r\n								<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><img alt=\"图片\" data-=\"\" data-img-idx=\"0\" src=\"http://b248.photo.store.qq.com/psb?/V148TWI01v1rR9/7.xBon229nsa2QZBGm0Ab6vBnYr2TmiGSPtU0qwG7tI!/b/dCBo05PVAQAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;bo=WAKLAQAAAAABAPc!&amp;t=5&amp;su=0145688065&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 600px; padding-right: 0px; height: 395px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /><br />\r\n								(1)二战结束后，德国依据所属阵营的不同，被分割成两个国家：民主德国与联邦德国。1961年8月12日民主德国（即东德)通过的法令，于8月12～13日夜间修筑。目的是制止东德居民包括熟练技工大量流入西德。这是一组1961年拍摄的照片，记录了一位17岁的小伙在东德统治下，冒死翻越柏林墙在西德警察帮助下投奔西德的全过程。<br />\r\n								<br />\r\n								<br />\r\n								<img alt=\"图片\" data-=\"\" data-img-idx=\"1\" src=\"http://b258.photo.store.qq.com/psb?/V148TWI01v1rR9/gjA4rY6umVVIZQRvRdC0dj7ZOpEWNLKZN84iDlt0MI8!/b/dCl10pmAEQAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;bo=WAK*AQAAAAABAMM!&amp;t=5&amp;su=024484129&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 600px; padding-right: 0px; height: 447px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /><br />\r\n								(2)东德男子冒死翻越柏林墙的地点。<br />\r\n								<br />\r\n								<br />\r\n								<br />\r\n								<img alt=\"图片\" data-=\"\" data-img-idx=\"2\" src=\"http://b248.photo.store.qq.com/psb?/V148TWI01v1rR9/murHGdA5nX*YIo.VhyTceBkZ1NrLSg9WZr.BBHDKW.c!/b/dGao35O3AQAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;bo=WAKJAQAAAAABAPU!&amp;t=5&amp;su=0166328769&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 600px; padding-right: 0px; height: 393px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /><br />\r\n								(3)东德男子正在翻越柏林墙。<br />\r\n								<br />\r\n								<br />\r\n								<br />\r\n								<img alt=\"图片\" data-=\"\" data-img-idx=\"3\" src=\"http://b248.photo.store.qq.com/psb?/V148TWI01v1rR9/HxtsZNdFaVCN4oWrDJ0DSKgwRz*AU49.N956CZBmTmA!/b/dB4U25OSAQAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;bo=WAKNAQAAAAABAPE!&amp;t=5&amp;su=0130011153&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 600px; padding-right: 0px; height: 397px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /><br />\r\n								(4)东德男子正在翻越柏林墙。<br />\r\n								<br />\r\n								<br />\r\n								<br />\r\n								<img alt=\"图片\" data-=\"\" data-img-idx=\"4\" src=\"http://b249.photo.store.qq.com/psb?/V148TWI01v1rR9/ZciQSlZr3GKnS0pts9M9I1m3KO8X5sL..rP2T9BE9fA!/b/dMejdpTjAQAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;bo=WAKXAQAAAAABAOs!&amp;t=5&amp;su=0240023377&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 600px; padding-right: 0px; height: 407px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /><br />\r\n								(5)东德男子正在翻越柏林墙。<br />\r\n								<br />\r\n								<br />\r\n								<br />\r\n								<img alt=\"图片\" data-=\"\" data-img-idx=\"5\" src=\"http://b258.photo.store.qq.com/psb?/V148TWI01v1rR9/GeJQ0RBAhF4oagrns8RyHw9nDrwV63H*WUEnvGx4vGg!/b/dFFhz5kaEQAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;bo=WAKSAQAAAAABAO4!&amp;t=5&amp;su=0173980369&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 600px; padding-right: 0px; height: 402px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /><br />\r\n								(6)东德男子正在翻越柏林墙。<br />\r\n								<br />\r\n								<br />\r\n								<br />\r\n								<img alt=\"图片\" data-=\"\" data-img-idx=\"6\" src=\"http://b247.photo.store.qq.com/psb?/V148TWI01v1rR9/HChdPfzLbzV5fJYXsH4AFzL0PypnIVyAmoTE3KMO3*o!/b/dAR2QpNyAQAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;bo=WAKDAQAAAAABAP8!&amp;t=5&amp;su=0166492961&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 600px; padding-right: 0px; height: 387px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /><br />\r\n								(7)西德警察。<br />\r\n								<br />\r\n								<br />\r\n								<br />\r\n								<img alt=\"图片\" data-=\"\" data-img-idx=\"7\" src=\"http://b258.photo.store.qq.com/psb?/V148TWI01v1rR9/SweNAJfPBSbzUCb60XguxZnVRUcVaR*vD*9dyb.mRTs!/b/dChc0pnFEgAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;bo=WAKhAQAAAAABAN0!&amp;t=5&amp;su=0165662945&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 600px; padding-right: 0px; height: 417px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /><br />\r\n								(8)西德警察帮助东德男子翻越柏林墙。<br />\r\n								<br />\r\n								&nbsp;</span></div>\r\n						</div>\r\n					</div>\r\n				</div>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<br class=\"Apple-interchange-newline\" />\r\n', '0', '1', '1', '2016-09-28 08:57:25', null, '0');
INSERT INTO `entry` VALUES ('223', '76', '[转贴]追忆柏林墙 2014-1-30 19:58 阅读(0)', '<p>\r\n	&nbsp;</p>\r\n<table cellpadding=\"0\" cellspacing=\"0\" id=\"blogContentTable\" style=\"position: relative; padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px; padding-left: 0px; border-spacing: 0px; width: 880px; padding-right: 0px; border-collapse: collapse; font: 12px/19px punctuation, 微软雅黑, Tohoma; white-space: normal; table-layout: fixed; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<tbody style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n		<tr style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n			<td style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; word-wrap: break-word; padding-top: 0px\" valign=\"top\">\r\n				<div id=\"blogContainer\" style=\"position: relative; padding-bottom: 0px; margin: 0px; padding-left: 16px; padding-right: 16px; height: 6448px; overflow: hidden; padding-top: 0px\">\r\n					<div align=\"center\" class=\"lp_title_type_3\" id=\"paperTitleArea\" style=\"background-image: url(/qzone/space_item/orig/9/81177_t5.gif); padding-bottom: 0px; margin: 0px 0px 35px 72px; padding-left: 0px; width: 690px; padding-right: 0px; background-repeat: no-repeat; background-position: 50% 50%; height: 70px; padding-top: 0px\">\r\n						<span id=\"paperTitle\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; display: block; color: rgb(0,0,0); word-break: break-all; padding-top: 25px\"><font color=\"#000000\" face=\"微软雅黑\" style=\"font-size: 26px\">[转贴]追忆柏林墙</font></span></div>\r\n					<div data-webp-ctx-e=\"1\" id=\"blogDetailDiv\" style=\"padding-bottom: 0px; margin: 0px; min-height: 380px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); font-size: 14px; padding-top: 0px\">\r\n						<div class=\"blog_details_20120222\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n							<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n								<a href=\"http://club.kdnet.net/dispbbs.asp?boardid=33&amp;id=1967217\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\">http://club.kdnet.net/dispbbs.asp?boardid=33&amp;id=1967217</a><br />\r\n								<br />\r\n								追忆柏林墙<br />\r\n								<br />\r\n								<a href=\"http://www.lotour.com/imagessnapshot/20070713/s115215742.JPG\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" data-=\"\" data-img-idx=\"0\" src=\"http://www.lotour.com/imagessnapshot/20070713/s115215742.JPG?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; cursor: pointer; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								肯尼迪在柏林墙边的演说：<br />\r\n								<br />\r\n								<a href=\"http://images.qianlong.com/mmsource/imagesgather/2007/11/9/pic12007110911455275094.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" data-=\"\" data-img-idx=\"1\" src=\"http://images.qianlong.com/mmsource/imagesgather/2007/11/9/pic12007110911455275094.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; cursor: pointer; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								Kennedy<br />\r\n								<br />\r\n								　　二千年以前，最自豪的夸耀是Civitas Romanus sum，今天，自由世界最自豪的夸耀是Ich bin ein Berliner。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　世界上有许多人确实不懂，或者说他们不明白什么是自由世界和共产主义世界的根本分歧。让他们来柏林吧。有些人说，共产主义是未来的潮流。让他们来柏林吧。有些人说，我们能在欧洲或其他地方与共产党人合作。让他们来柏林吧。甚至有那么几个人说，共产主义确是一种邪恶的制度，但它可以使我们取得经济发展。&ldquo;Lasst sie nach Berlin kommen.&rdquo;<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　自由有许多困难，民主亦非完美，然而我们从未建造一堵墙把我们的人民关在里面，不准他们离开我们 。我愿意我的同胞们&mdash;&mdash;他们与你们远隔千里住在大西洋彼岸&mdash;&mdash;说，他们为能在远方与你们共有过去十八年的经历感到莫大的骄傲。我不知道还有哪一个城镇或都市被围困十八年仍葆有西柏林的这种生机、力量、希望和决心。全世界都看到，柏林墙最生动最明显地表现出一种失败。但我们对此并不感到称心如意，因为柏林墙既是对历史也是对人性的冒犯，它拆散家庭，造成妻离子散骨肉分离，把希冀统一的一个民族分成两半。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　这个城市的事实也用于整个德国&mdash;&mdash;只要四个德国人中有一个被剥夺了自由人的基本权利，即自由选择的权利，那么欧洲真正持久的和平便绝无可能实现。经过保持和平与善意的十八年，这一代德国人终于赢得自由的权利，包括在持久和平中善所有的人民，实现家庭团聚和民族统一的权利。你们住在受到保护的一座自由之岛上，但你们的生活是大海的一部分。因此让我在结束讲话时请求你们抬起目光，超越今日的危险看到明天的希望；超越这道墙看到正义的生平来临的一天；超越你们自己和我们自己看到全人类。自由是不可分割的，只要一人被奴役，所有的人都不自由。当所有的人都自由了，那时我们便能期待这一天的到来：在和平与希望的光辉中这座城市获得统一，这个国家获得统一，欧洲大陆获得统一。当这一天最终来临&mdash;&mdash;它必将来临&mdash;&mdash;时，西柏林人民将能对这一点感到欣慰：几乎二十年时间里他们站在第一线。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　一切自由人，不论他们住在何方，皆是柏林市民，所以作为一个自由人，我为&ldquo;Ich bin ein Berliner&rdquo;这句话感到自豪。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								历史见证：越过柏林墙，寻求自由<br />\r\n								<br />\r\n								&nbsp;&nbsp;&nbsp;&nbsp;柏林墙由12公里长的水泥墙和137公里长的铁丝网组成，包括有116个观望台，随后经过了四次改建和加固。柏林墙一共截断了192条街道（97条在柏林内，95条为柏林通向东德的道路），32条铁路线，8条轻轨和4条地铁以及3条高速公路。边界上的河流、湖泊也被禁止通航，并加以监视。西柏林变成了一座孤岛。谁想在西柏林与西德之间旅行，则必须通过边境的严格检查。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_cbc25d23394c000ebbcezQtGwd33Gzdt.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_cbc25d23394c000ebbcezQtGwd33Gzdt.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								　　第二次世界大战结束后，德国被分为4个区域，分别由法国、英国、美国和苏联接管，后来前三方合并，而苏联接管的地区变得更加孤立。这条1953年拉起的钢丝围栏把很多德国朋友分开了。<br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_ad2e1b91300b4144504awOZtn8kZ7k3U.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_ad2e1b91300b4144504awOZtn8kZ7k3U.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;随着苏联和西方国家紧张局势的加剧，不同地区间的通道逐渐缩小。1961年，这条边界被正式化地变成了一堵砖墙，照片中东德士兵和工人正在给柏林墙增加高度。<br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_28b2f0394e39939d76742T42vW4q5Zle.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_28b2f0394e39939d76742T42vW4q5Zle.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								柏林墙把千千万万的德国家庭分隔开来，许多居住在东部的德国人无法再去西部上班。<br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_0feab636fc11b917d848iVekYTDKlaIY.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_0feab636fc11b917d848iVekYTDKlaIY.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								沿墙而行的街道也都被割裂开来，许多交通工具无法再在那里行驶。<br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_a9265c9e40999394a9eampKCVOe2Izrx.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_a9265c9e40999394a9eampKCVOe2Izrx.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								多年来很多东德人试图逃到西边去。图为1961年一名17岁的东德男孩翻越柏林墙，两名西德警察正在帮助他安全地下来。<br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_010942349cc27d97f3673J08U0mkgU1f.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_010942349cc27d97f3673J08U0mkgU1f.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								柏林墙建成后，西柏林变成了一片孤独的、被敌视和被包围的土地。<br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_42c518489aa13133f290fgUzS2YAqG1d.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_42c518489aa13133f290fgUzS2YAqG1d.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								在柏林墙位于奥巴鲍姆桥的检查站，两名东德边界警卫锁好大门后离开。<br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_c81cbcdadf1cdedf1e4eg2qUCqC9DaXm.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_c81cbcdadf1cdedf1e4eg2qUCqC9DaXm.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								美国总统肯尼迪于1963年访问柏林墙位于勃兰登堡门的关口，他在发表演讲时用德语说：我是一个柏林人(ICH BIN EIN BERLINER)。这句话后来成为名言。<br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_9bebf6f995359c3f5882sP2pJ6utGpyk.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_9bebf6f995359c3f5882sP2pJ6utGpyk.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								逃到西德的东德女孩在和妈妈隔墙说话。<br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_720b0932d84f64dffd54UxcNBFFOU13U.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_720b0932d84f64dffd54UxcNBFFOU13U.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								到上世纪80年代中期，柏林墙已经成为冷战的最持久象征。<br />\r\n								<br />\r\n								<a href=\"http://www.lotour.com/imagessnapshot/20070716/s100341921.JPG\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" data-=\"\" data-img-idx=\"12\" src=\"http://www.lotour.com/imagessnapshot/20070716/s100341921.JPG?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; cursor: pointer; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								　　&ldquo;自由有许多困难，民主亦非完美，然而我们从未建造一堵墙把我们的人民关在里面，不准他们离开我们。&rdquo; &mdash;&mdash;肯尼迪《柏林墙下的演说》1963年6月25日于西德市政厅柏林墙前。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								<a href=\"http://www.lotour.com/imagessnapshot/20070716/s100402525.JPG\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" data-=\"\" data-img-idx=\"13\" src=\"http://www.lotour.com/imagessnapshot/20070716/s100402525.JPG?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; cursor: pointer; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								柏林墙<br />\r\n								<br />\r\n								　　地面逃亡最简单的方式是直接翻墙而过。看上去一人多高的墙可以翻身而上。但逃亡者从开始在边境开阔地带奔跑到墙下，再翻身跃上墙的这段时间内，生与死就完全听天由命了。1961年，当十八岁的东柏林青年彼得&middot;费希特尔在到达墙跟翻身跃墙，他已经爬到了柏林墙的顶部，只需要再加最后一把劲，就可以达成目标，就在这个时候，枪声响了&hellip;&hellip;<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　彼得滑落回柏林墙东侧。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　悲剧还没有完，身中数弹的彼得倒在柏林墙下，血流如注，这期间，他不停地呼喊救命，呼声惊动了西柏林一边的边防军人。军人们扔过来一个急救包，但血将流尽的彼得&middot;费希特尔已无力自救。彼得就这样在墙下躺了50分钟，没有一个东德警察前来管他。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　彼得的呼喊声一点一点的低下去了，低下去了。西柏林的人群爆发出愤怒的抗议声。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　&ldquo;你们是杀人犯&rdquo;&ldquo;你们是法西斯！&rdquo;上千群众怒吼着。西德的警察冒险跑到柏林墙边（这是极其危险的，柏林墙西侧依然是东德的土地，警察已经&ldquo;越界&rdquo;，完全可能被枪击）翻身跃墙将这位东德青年抬起来，但是太晚了，彼得已经停止了呼吸。他的血已经流尽了，在他蓝眼睛里最后映出的，依然是东柏林。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　这是柏林墙将柏林城和它的人民分割以来，第一位在逃亡中死于枪击的东柏林市民。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　如果说彼得最大的不幸在于他最终没有成功，我不知道下面这个最后&ldquo;成功&rdquo; 的例子，是不是算幸运。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　在柏林墙刚完成的那一年，由于墙还不是很坚固，有人就想出了办法，开重型车辆直接撞墙，直接冲开柏林墙进入西德。1961年，这类事件多达14起。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　逃亡者要面对的绝不仅仅是坚固的高墙，还有来自军队和警察的密集射击。而在枪林弹雨中全速前进去撞一堵大墙的行为，毫无疑问是&ldquo;双重自杀行为&rdquo;。而这却是当年东德一些逃亡者们投生的方式。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　布鲁希克和他的同伙就是利用大客车冲击柏林墙，但是他们的行动从一开始就被发现了。军队和警察从多个方向向客车密集射击，客车起火燃烧，弹痕累累！还好，客车质量过硬，不但没有熄火，还在布鲁希克良好的驾驶下奋勇加速，一声巨响，柏林墙被撞开了一个大缺口，整个客车冲进了西柏林！<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　欢呼的人群拥上来迎接，却被眼前的景象震惊了，驾驶座上的布鲁希克身中19弹，他是用生命的最后意志坚持加速，冲向柏林墙的。当客车冲进西柏林的那一刻，布鲁希克停止了呼吸。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　柏林人展开了一场争论，布鲁希克究竟有没有看到他梦想看到的西柏林？最后是一个现场镜头宽慰了大家，从镜头上看，客车驾驶座位于西柏林之后，布鲁希克还有一个抬头的动作。是的，那时候他还活着！他的眼睛最后映出的，是他梦想中的自由世界－西柏林！他是一个成功者。<br />\r\n								<br />\r\n								　　另一个传奇式的故事是空中热气球逃亡。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　1979年的一个深夜，东德黑色夜幕的上空出现了一个高度为28米的欧洲历史上最大体积的热气球。当这个热气球接近柏林墙地域时，被东柏林地面警卫发现。三束探照灯直射黑色天幕，追踪监视着这个看来企图越境朝西柏林飘去的热气球。就在地面警卫朝这来历不明的巨大热气球开枪射击之前，热气球迅速高升，爬上了两千六百米高空，随后不知去向。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　这个热气球的吊蓝里，装着两个东德的家庭，大人小孩一共八口人。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　他们在快速升高后，可能由于慌乱，失去了方向。当在空中飞行28分钟后，热气球安全降落地面。悄悄掀开覆盖了他们的巨大气球布，看看外围环境：丛林荒草，远近没有人烟。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　他们无法判断究竟是到了自己的目的地西德，还是不过在空中转了一个圈，仍在东德境内。或者，已经非法进入了其他国家的土地。他们不知该如何是好。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　他们既非科学家又非运动员，虽然对气体动力学一无所知，但自从萌生了用热气球逃出东德的想法，就开始白手起家。买来了有关的书籍，从头学习有关原理。买来大量的纺织品，利用自己研制的相关设备一次次实验将要充当气球外体的布的质量。气象学要掌握、操作要掌握，材料学、工程学、物理、化学、力学等等知识都需要。后来，那个奇迹终于悄悄地在这一对普通东德人家的房顶下诞生了。在那个神不知，鬼不觉的深夜，那个欧洲最大的热气球载着两家人的希望和梦想，升上了东德阴霾的天空。他们什么都想到了：出境前被打落坠地、被逮捕入狱，出境后落入海中或落在人家房顶，落在城市中心等等，无论什么意外事故发生，好歹总要面对一个结局。他们就是没想到，什么意外也没发生，但当气球安全着陆时，竟是真相不明，无人理睬，没有下文。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　两对年轻的父母，带着四个年幼的孩子，闷在气球巨大的布面下，把未来的结局想设想了一遍又一遍：走出这泄了气的热气球，要么被东德政府关进监狱，要么向其他什么国家的政府投案自首，要么在西德安居乐业，重获新生。想想为这次逃亡而长久地呕心沥血，看看四个无辜的孩子，他们无法承受被东德政府关进监狱的命运，不敢走出气球；或者他们干脆把命运交给了上帝，听天由命。他们唯一能作的，就是祈祷。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　降落整整24小时以后，军人来了，揭开了气球。他们对这8个逃亡者说出了他们盼望了多少年的话。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　&ldquo;你们自由了！这里是西德的领土&rdquo;。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　1987年6月12日清晨，美国总统里根抵达柏林，此时这座城市正在庆贺其750岁诞辰。在将东西柏林割裂20余年的分界线&mdash;&mdash;勃兰登堡门的柏林墙前，里根发表了著名的演讲。演讲稿由秘书起草，听者主要是正意欲与美国缔结友好关系的对象&mdash;&mdash;苏联领导人米哈伊尔&middot;戈尔巴乔夫，还有届时在场的2万名听众。<br />\r\n								<br />\r\n								　　在这次著名的演讲中，里根呼吁戈尔巴乔夫拆掉柏林墙，这一言辞遭到美国国务院和国家安全委员会的强烈反对，他们担心克里姆林宫的强硬派会以此向戈氏提出质疑。那天下午，不到2时，里根走上讲台。因为担心会有恐怖袭击，里根身后放置了两块巨大的防弹玻璃。<br />\r\n								<br />\r\n								　　里根总统说出了以下这段震撼世界的话：&ldquo;戈尔巴乔夫总书记，如果你要寻求和平，如果你要为苏联和东欧寻求繁荣，如果你要寻求自由：就到这扇门来吧！戈尔巴乔夫先生，打开这扇门！戈尔巴乔夫先生，拆掉这堵墙！&rdquo;<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_6b8afd2eff6a0e5511dbqE2JytE9RdIo.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_6b8afd2eff6a0e5511dbqE2JytE9RdIo.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_5c7bcb8f82634e1177e8ILV732NZuURj.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_5c7bcb8f82634e1177e8ILV732NZuURj.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								1987年6月，美国总统里根访问柏林，从德国国会大厦的阳台上观看柏林墙。<br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_3e4c85f2f6cccf584961TuaWeBQKkvUQ.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_3e4c85f2f6cccf584961TuaWeBQKkvUQ.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								1987年6月，里根在西柏林勃兰登堡门发表演说，在提到戈尔巴乔夫时说了一句话：&ldquo;戈尔巴乔夫先生，拆掉这堵墙吧。&rdquo;<br />\r\n								<br />\r\n								　　历史的进程到了1989年下半年，东德已经是强弩之末。由于东德政府70年代以来所实行的指令性经济、农业全面集体化、强力发展重工业、严厉打击国内反对声音的经济、政治政策，导致经济发展几乎停滞，210亿美元的外债债台高筑、东德马克内债累累，环境污染严重，人民生活贫穷压抑，严重的不满情绪早以深深埋伏在社会民心之中。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　1989年11月9日，新东德政府开始计划放松对东德人民的旅游限制，但由于当时东德的中央政治局委员君特&middot;沙博夫斯基对上级命令的误解，错误地宣布柏林墙即将开放，导致数以万计的市民走上街头。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　这一天，就象上紧了发条的钟表，突然失去指针，滴滴答答的钟声尤在，却不知何始何终&mdash;&mdash;柏林墙的两面人山人海，鸦雀无声。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　面对这面耸立了28年，阻绝两德人民，制造了无数悲欢离合、生死哭歌、惨重牺牲的血墙，人们无法判断的是，当制造它的独裁政府部门和官员辞职的辞职，改选的改选时，柏林墙辞职了吗？它是否仍然戒备森严？它还能随意射杀越墙的逃亡者吗？自动射击装置是否完全解除？密堡暗碉里的岗哨是否仍然轮流值班？带缰绳可以自由追踪１００米的警犬是否正严阵以待？<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　没有任何官方的媒体报道这些与人们生息密切相关的消息。柏林墙依然无声地矗立着。它两面成千上万被阻隔的人们遥遥相对，心中纵有万马奔腾，脚却不敢越雷池一步。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　这是继两次世界大战之后，德国又一个历时转折的关头。而历史在这一瞬间干脆停下了脚步，为的是让人们记住它的沧桑。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　不知道渴望自由的人们同这面血墙对视了多久，终于有一个东德的青年人，壮着胆子，往那禁区的空地，试探着，迈出一只脚&hellip;&hellip;<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　没有反应。让脚落地，移动身体重心，再迈出另一只脚&hellip;&hellip;<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　仍然没有发现任何警戒方面的反应。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　小伙子双脚落在东柏林境内的禁区，人，暴露在自动枪击射程之内。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　柏林墙两岸，无数双眼睛被这年轻的躯体所抓住，人们不约而同屏神静息等待着&hellip;&hellip;要么枪声乍起，又一具尸体倒卧在血泊中；要么人民淹没、踏碎这围墙。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　小伙子不急不徐，却一步千斤，载着两德的万众一心，牵着两德张开的手臂，在众目暌暌之下，从那片社会主义东德境内的边境开阔地，一寸一寸、一米一米走向资本主义西柏林境内。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　这应当是德国历史上，街头上最安静最紧张的时刻了。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　当小伙子在身前身后人山人海的无声的注视下，终于接近柏林墙，奋力攀上墙顶，预期的枪声仍然没有响起，紧张的人们却沉默得几乎要爆炸。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　然后，西柏林一边向这位以命相抵、探试自由的青年人伸出了丛林般的手臂；然后，小伙子双脚结结实实踏上了西柏林自由的土地。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　一瞬间，柏林墙两岸人声鼎沸，心旌摇荡，激动的情感潮流如洪水决堤。人们相互拥抱接吻，相互重复诉告着那个刚刚发现的不可思议的事实：<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　柏林墙解放了。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　它的警卫事实上以然解除。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　它已经全然不过就是一堵墙而已了。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　两德人们相互拥入对方，成千上万的人们彻夜不眠地享受着亲友重逢的喜悦。两德人民拥满柏林墙墙上墙下墙东墙西，人们举杯相庆，奏乐狂欢，欢乐的自发的庆典持续数日，节日的气氛经久不消。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　无论如何，柏林墙的故事已经结束了。而且，是喜剧性的结束。人间的故事，如柏林墙这般悲惨的并不少，能够最终这样收场的，已经很不错了。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　德国人毕竟是幸运的，柏林墙见证了德国人的痛苦，全世界分享了他们的痛苦。他们被关注着。然而，还有那么多的人，他们的痛苦竟然是完全默然的。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								　　柏林墙倒下了，东德人终于获得了他们梦寐以求的自由，然而，类似的悲剧却并没有在这里地球上结束，我们看到在远隔德国万里重洋的另外一个国家，依旧有一堵用来对付自己的百姓的墙巍峨耸立着，唯一的区别是，大多数人看不到甚至不知道这堵墙。<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_038a9ff9337f55b3555bWb2S5pUwY0O3.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_038a9ff9337f55b3555bWb2S5pUwY0O3.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								1989年11月9日，东德领导人埃根&middot;克伦兹批准了&ldquo;迁徙自由的新旅行法&rdquo;，千千万万民众潮水般地涌向西柏林。<br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_d3eb4dba570d4984c1f5qzO8OKkaNEO6.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_d3eb4dba570d4984c1f5qzO8OKkaNEO6.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								<a href=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_342aae9a6659d287a589dHSxveVBs98V.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://www.51cdv.com/bbs/attachments/day_071114/20071114_342aae9a6659d287a589dHSxveVBs98V.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								东西德国人的手一起拉下了柏林墙上的铁丝网<br />\r\n								<br />\r\n								<a href=\"http://cimg2.163.com/cnews/2006/11/3/20061103104509a2f76.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" data-=\"\" data-img-idx=\"20\" src=\"http://cimg2.163.com/cnews/2006/11/3/20061103104509a2f76.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; cursor: pointer; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								<a href=\"http://bbs.ynet.com/attachments/day_070314/20070314_92b36802b1ea843f637azVfyRoeqFnAF.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" src=\"http://bbs.ynet.com/attachments/day_070314/20070314_92b36802b1ea843f637azVfyRoeqFnAF.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								东西德国人的手一起拉下了柏林墙上的铁丝网<br />\r\n								&nbsp;</div>\r\n						</div>\r\n					</div>\r\n				</div>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<br class=\"Apple-interchange-newline\" />\r\n', '0', '1', '1', '2016-09-28 09:00:30', null, '0');
INSERT INTO `entry` VALUES ('224', '76', '柏林墙组图 2014-1-30 19:50 阅读(0)', '<p>\r\n	&nbsp;</p>\r\n<table cellpadding=\"0\" cellspacing=\"0\" id=\"blogContentTable\" style=\"position: relative; padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px; padding-left: 0px; border-spacing: 0px; width: 880px; padding-right: 0px; border-collapse: collapse; font: 12px/19px punctuation, 微软雅黑, Tohoma; white-space: normal; table-layout: fixed; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<tbody style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n		<tr style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n			<td style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; word-wrap: break-word; padding-top: 0px\" valign=\"top\">\r\n				<div id=\"blogContainer\" style=\"position: relative; padding-bottom: 0px; margin: 0px; padding-left: 16px; padding-right: 16px; height: 3935px; overflow: hidden; padding-top: 0px\">\r\n					<div align=\"center\" class=\"lp_title_type_3\" id=\"paperTitleArea\" style=\"background-image: url(/qzone/space_item/orig/9/81177_t5.gif); padding-bottom: 0px; margin: 0px 0px 35px 72px; padding-left: 0px; width: 690px; padding-right: 0px; background-repeat: no-repeat; background-position: 50% 50%; height: 70px; padding-top: 0px\">\r\n						<span id=\"paperTitle\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; display: block; color: rgb(0,0,0); word-break: break-all; padding-top: 25px\"><font color=\"#000000\" face=\"微软雅黑\" style=\"font-size: 26px\">柏林墙组图</font></span></div>\r\n					<div data-webp-ctx-e=\"1\" id=\"blogDetailDiv\" style=\"padding-bottom: 0px; margin: 0px; min-height: 380px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); font-size: 14px; padding-top: 0px\">\r\n						<div class=\"blog_details_20120222\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n							<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n								&nbsp;<a href=\"http://club.kdnet.net/dispbbs.asp?boardid=1&amp;id=537055\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\">http://club.kdnet.net/dispbbs.asp?boardid=1&amp;id=537055</a>&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n								<br />\r\n								<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">柏林墙大事记<br />\r\n								<br />\r\n								<br />\r\n								&nbsp;&nbsp;1945年 德国战败投降，柏林分别被美、英、法、苏划分为四块占领区。<br />\r\n								<br />\r\n								<br />\r\n								&nbsp;&nbsp;1948年6月24日 前苏联军队构筑封锁线把柏林一分为二，使柏林成为冷战时期东西方对抗的最前沿。<br />\r\n								<br />\r\n								<br />\r\n								&nbsp;&nbsp;1949年-1961年8月12日 大约有269万东德人通过东、西柏林的81个通道纷纷逃向西部，占当时东德人口的1/6。<br />\r\n								<br />\r\n								<br />\r\n								&nbsp;&nbsp;1961年8月13日 民主德国决定封锁西柏林四周的边界，随后关闭勃兰登堡门，在分界线上建筑了隔离设施，总长达165公里，通称&ldquo;柏林墙&rdquo;。<br />\r\n								<br />\r\n								<br />\r\n								&nbsp;&nbsp;1961年8月24日 发生第一次枪击逃亡者事件，截至1989年，共有61人被边防哨兵枪杀。<br />\r\n								<br />\r\n								<br />\r\n								&nbsp;&nbsp;1961年10月27日 美苏两方十几辆坦克在柏林墙两侧相隔100米对峙十几个小时，第三次世界大战一触即发。<br />\r\n								<br />\r\n								<br />\r\n								&nbsp;&nbsp;1971年 四国协定允许放弃任何单方改变柏林现状的尝试，给西柏林人一个自由出入城市和在东柏林探亲的国际法保证。<br />\r\n								<br />\r\n								<br />\r\n								&nbsp;&nbsp;1989年9月11日 成千上万的东德人借道奥地利和匈牙利边境再次向西德逃亡，史称&ldquo;公民大逃亡&rdquo;。<br />\r\n								<br />\r\n								<br />\r\n								&nbsp;&nbsp;1989年11月9日 下午6时57分，民主德国宣布从即时起开放边境。聚集在柏林墙附近的德国人很快就拆除了这个横在德国人中间的高墙，史称&ldquo;柏林墙倒塌&rdquo;。<br />\r\n								<br />\r\n								<br />\r\n								&nbsp;&nbsp;1990年10月2日 原民主德国的国旗徐徐降下。 1990年10月3日零时：在柏林帝国议会大厦前，联邦德国国旗徐徐升起，分裂长达45年之久的德国终于统一了。<br />\r\n								<br />\r\n								<br />\r\n								柏林墙的由来<br />\r\n								<br />\r\n								<br />\r\n								&nbsp;&nbsp; 柏林墙的正式名称叫&quot;反法西斯防卫墙&quot;，是第二次世界大战和东西方冷战关系的产物。<br />\r\n								<br />\r\n								<a href=\"http://www.epicbook.com/picture/country/euorpe/www_epicbook_com_berlin_1.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" data-=\"\" data-img-idx=\"0\" src=\"http://www.epicbook.com/picture/country/euorpe/www_epicbook_com_berlin_1.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; cursor: pointer; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								红色线条即是柏林墙位置<br />\r\n								<br />\r\n								&nbsp;&nbsp;&nbsp;&nbsp;1945年5月8日，纳粹德国投降。战败的德国不仅丧失了战前和战争期间吞并的别国领土，而且根据1945年美、英、苏三国克里米亚声明和波茨坦协定，东普鲁士和奥得--尼斯河以东的约11.4万平方公里的德国领土分别割让给了苏联和波兰，其余的德国领土和首都大柏林市则由美苏英法4国分区占领，建立4个占领区，并由4国组成&ldquo;盟国管制委员会&rdquo;，接管德国的最高权力。<br />\r\n								<a href=\"http://www.de0049.com/lscl/img_ww2/30yalta_zoom.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" data-=\"\" data-img-idx=\"1\" src=\"http://www.de0049.com/lscl/img_ww2/30yalta_zoom.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								1945年2月4日-11日，邱吉尔、罗斯福、斯大林在雅尔塔举行会晤，签订《雅尔塔协定》。<br />\r\n								<br />\r\n								<a href=\"http://www.de0049.com/lscl/img_ww2/33attackbolin_zoom.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" data-=\"\" data-img-idx=\"2\" src=\"http://www.de0049.com/lscl/img_ww2/33attackbolin_zoom.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								1945年4月30日，柏林被攻克。图为苏军在国会大厦的屋顶上升起苏联国旗。<br />\r\n								<br />\r\n								<br />\r\n								<br />\r\n								<a href=\"http://www.de0049.com/lscl/img_ww2/34signature_zoom.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" data-=\"\" data-img-idx=\"3\" src=\"http://www.de0049.com/lscl/img_ww2/34signature_zoom.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								1945年5月7日，德国海军上将Von Friedeburg在美国艾森豪威尔将军的法国指挥部签署无条件投降文件。<br />\r\n								<a href=\"http://www.epicbook.com/picture/history/berlin_1.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" data-=\"\" data-img-idx=\"4\" src=\"http://www.epicbook.com/picture/history/berlin_1.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; cursor: pointer; border-right: 0px; padding-top: 0px\" /></a><a href=\"http://www.de0049.com/lscl/lscl_border.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\" title=\"新窗口打开\"><img border=\"0\" data-=\"\" data-img-idx=\"5\" src=\"http://www.de0049.com/lscl/lscl_border.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a><br />\r\n								<br />\r\n								根据1945年美、英、苏三国克里米亚声明和波茨坦协定，东普鲁士和奥得--尼斯河以东的约11.4万平方公里的德国领土分别割让给了苏联和波兰，其余的德国领土和首都大柏林市则由美苏英法4国分区占领，建立4个占领区，并由4国组成&ldquo;盟国管制委员会&rdquo;，接管德国的最高权力。<br />\r\n								<br />\r\n								&nbsp;</span></div>\r\n						</div>\r\n					</div>\r\n				</div>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<br class=\"Apple-interchange-newline\" />\r\n', '0', '1', '1', '2016-09-28 09:00:53', null, '0');
INSERT INTO `entry` VALUES ('225', '76', '飞跃柏林墙 2014-1-30 19:49 阅读(0)', '<div align=\"center\" class=\"lp_title_type_3\" id=\"paperTitleArea\" style=\"background-image: url(/qzone/space_item/orig/9/81177_t5.gif); padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 35px 72px; padding-left: 0px; width: 690px; padding-right: 0px; background-repeat: no-repeat; font: 12px/19px punctuation, 微软雅黑, Tohoma; white-space: normal; background-position: 50% 50%; letter-spacing: normal; height: 70px; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span id=\"paperTitle\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; display: block; color: rgb(0,0,0); word-break: break-all; padding-top: 25px\"><font color=\"#000000\" face=\"微软雅黑\" style=\"font-size: 26px\">飞跃柏林墙</font></span></div>\r\n<div data-webp-ctx-e=\"1\" id=\"blogDetailDiv\" style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); font-variant: normal; font-style: normal; text-indent: 0px; margin: 0px; min-height: 380px; padding-left: 0px; padding-right: 0px; font-family: punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(0,0,0); font-size: 14px; font-weight: normal; word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<div class=\"blog_details_20120222\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n		<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n			&nbsp;<a href=\"http://blog.sina.com.cn/s/blog_5f18712d0100fjl9.html\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\">http://blog.sina.com.cn/s/blog_5f18712d0100fjl9.html</a>&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n			<br />\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\">&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&ldquo;自由有许多困难，民主亦非完美，然而我们从未建造一堵墙把我们的人民关在里面，不准他们离开。&rdquo;</strong><br />\r\n				&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&mdash;&mdash;<font style=\"font-size: 14px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">肯尼迪《柏林墙下的演说》，1963年6月25日于西德市政厅柏林墙前。</strong></font></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\">&nbsp;</font></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span><font style=\"font-size: 18px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">从1961年8月13日拉起第一根铁篱，到1989年11月9日在人们的愤怒中轰然倒塌，柏林墙分割东西德长达28年，这座长160公里高3.6米的钢筋水泥怪兽曾血债高筑，惊世骇俗，以至于20年后人们看它的眼光依旧复杂。</strong></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 18px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; 如今依旧存在在这里的，是过去的伤痛，是现在的荣光，也是未来无上的希望&hellip;&hellip;</strong></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s5.sinaimg.cn/orignal/5f18712dg779e58187784&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img action-data=\"http%3A%2F%2Fs5.sinaimg.cn%2Fbmiddle%2F5f18712dg779e58187784%26690\" action-type=\"show-slide\" alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"0\" real_src=\"http://s5.sinaimg.cn/bmiddle/5f18712dg779e58187784&amp;690\" src=\"http://s5.sinaimg.cn/bmiddle/5f18712dg779e58187784?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">简易围墙</strong>（<font style=\"font-size: 14px\">第二次世界大战结束后，德国被分为4个区域，分别由法国、英国、美国和苏联接管，后来前三方合并，而苏联接管的地区变得更加孤立。这条1953年拉起的钢丝围栏把很多德国朋友分开了。）</font></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s13.sinaimg.cn/orignal/5f18712dg779e5d8e682c&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"1\" real_src=\"http://s13.sinaimg.cn/bmiddle/5f18712dg779e5d8e682c&amp;690\" src=\"http://s13.sinaimg.cn/bmiddle/5f18712dg779e5d8e682c?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></font></font></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\"><font style=\"font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">砖头&middot;墙</strong><span class=\"Apple-converted-space\">&nbsp;</span><font style=\"font-size: 14px\">（</font><font style=\"font-size: 14px\">随着苏联和西方国家紧张局势的加剧，不同地区间的通道逐渐缩小。1961年，这条边界被正式化地变成了一堵砖墙，照片中东德士兵和工人正在给柏林墙增加高度。）</font></font></font></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s4.sinaimg.cn/orignal/5f18712dg779e63036353&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"2\" real_src=\"http://s4.sinaimg.cn/bmiddle/5f18712dg779e63036353&amp;690\" src=\"http://s4.sinaimg.cn/bmiddle/5f18712dg779e63036353?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></font></font></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\"><font style=\"font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">分隔</strong><font style=\"font-size: 14px\">（柏林墙把千千万万的德国家庭分隔开来，许多居住在东部的德国人无法再去西部上班。）</font></font></font></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s3.sinaimg.cn/orignal/5f18712dg779e6c2d56c2&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"3\" real_src=\"http://s3.sinaimg.cn/bmiddle/5f18712dg779e6c2d56c2&amp;690\" src=\"http://s3.sinaimg.cn/bmiddle/5f18712dg779e6c2d56c2?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></font></font></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\"><font style=\"font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">逃离的后果</strong></font>（图为1961年一名17岁的东德男孩翻越柏林墙，两名西德警察正在帮助他安全地下来。）</font></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s4.sinaimg.cn/orignal/5f18712dg779f18add1c3&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"4\" height=\"301\" real_src=\"http://s4.sinaimg.cn/bmiddle/5f18712dg779f18add1c3&amp;690\" src=\"http://s4.sinaimg.cn/bmiddle/5f18712dg779f18add1c3?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 490px; padding-right: 0px; max-width: 500px; height: 323px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" width=\"489\" /></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font size=\"5\">逃离的后果</font></strong><font style=\"font-size: 14px\">（图为1962年，</font><font style=\"font-size: 14px\">18岁的东德少年彼得-费查在攀越柏林墙时被东德的警察射杀。）</font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s3.sinaimg.cn/orignal/5f18712dg779e71491e92&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"5\" real_src=\"http://s3.sinaimg.cn/bmiddle/5f18712dg779e71491e92&amp;690\" src=\"http://s3.sinaimg.cn/bmiddle/5f18712dg779e71491e92?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></font></font></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\"><font style=\"font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">墙的悲伤</strong></font>（柏林墙建成后，西德变成了一片孤独的、被敌视和被包围的土地。）</font></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s14.sinaimg.cn/orignal/5f18712dg779e7b2a9fad&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"6\" real_src=\"http://s14.sinaimg.cn/bmiddle/5f18712dg779e7b2a9fad&amp;690\" src=\"http://s14.sinaimg.cn/bmiddle/5f18712dg779e7b2a9fad?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">希望</strong></font>（逃到西德的东德女孩在和妈妈隔墙说话。）</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s3.sinaimg.cn/orignal/5f18712dg779e75a8b522&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"7\" real_src=\"http://s3.sinaimg.cn/bmiddle/5f18712dg779e75a8b522&amp;690\" src=\"http://s3.sinaimg.cn/bmiddle/5f18712dg779e75a8b522?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></font></font></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\">团结</font></strong>（美国总统肯尼迪于1963年访问柏林墙位于Brandenburg Gate的关口，他在发表演讲时用德语说：我是一个柏林人（ICH BIN EIN BERLINER）。这句话后来成为名言。）<br />\r\n				<a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s15.sinaimg.cn/orignal/5f18712dg779e808a24ce&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"8\" real_src=\"http://s15.sinaimg.cn/bmiddle/5f18712dg779e808a24ce&amp;690\" src=\"http://s15.sinaimg.cn/bmiddle/5f18712dg779e808a24ce?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></a></font></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\"><font style=\"font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">障碍</strong></font>（到上世纪80年代中期，柏林墙已经成为冷战的最持久象征。）</font></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s11.sinaimg.cn/orignal/5f18712dg725ca87b54fa&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font style=\"font-size: 22px\"><font style=\"font-size: 14px\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"9\" real_src=\"http://s11.sinaimg.cn/bmiddle/5f18712dg725ca87b54fa&amp;690\" src=\"http://s11.sinaimg.cn/bmiddle/5f18712dg725ca87b54fa?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></font></font></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\">历史性访问</font></strong><span class=\"Apple-converted-space\">&nbsp;</span>（1987年6月，美国总统里根访问柏林，从德国国会大厦的阳台上观看柏林墙。）</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s15.sinaimg.cn/orignal/5f18712dg779e981c737e&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"10\" real_src=\"http://s15.sinaimg.cn/bmiddle/5f18712dg779e981c737e&amp;690\" src=\"http://s15.sinaimg.cn/bmiddle/5f18712dg779e981c737e?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">著名的话语</strong></font>（1987年6月，里根在西柏林Brandenburg Gate发表演说，在提到戈尔巴乔夫时说了一句话：&ldquo;戈尔巴乔夫先生，拆掉这堵墙吧。&rdquo;）</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s4.sinaimg.cn/orignal/5f18712dg779e9bcf05a3&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"11\" real_src=\"http://s4.sinaimg.cn/bmiddle/5f18712dg779e9bcf05a3&amp;690\" src=\"http://s4.sinaimg.cn/bmiddle/5f18712dg779e9bcf05a3?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">峰会</strong></font>（1987年，里根和戈尔巴乔夫在美国首都华盛顿会晤。）</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s3.sinaimg.cn/orignal/5f18712dg779e9f5a9922&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"12\" real_src=\"http://s3.sinaimg.cn/bmiddle/5f18712dg779e9f5a9922&amp;690\" src=\"http://s3.sinaimg.cn/bmiddle/5f18712dg779e9f5a9922?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">相隔28年的重逢</strong></font>（1989年11月9日，东德领导人埃根&middot;克伦兹批准了&ldquo;迁徙自由的新旅行法&rdquo;，千千万万民众潮水般地涌向西柏林。）</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s6.sinaimg.cn/orignal/5f18712dg779f44ba9be5&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"13\" real_src=\"http://s6.sinaimg.cn/bmiddle/5f18712dg779f44ba9be5&amp;690\" src=\"http://s6.sinaimg.cn/bmiddle/5f18712dg779f44ba9be5?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font size=\"5\">挣脱</font></strong>（东西德国人的手一起拉下了柏林墙上的铁丝网。）</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s6.sinaimg.cn/orignal/5f18712dg779ea3406d45&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"14\" real_src=\"http://s6.sinaimg.cn/bmiddle/5f18712dg779ea3406d45&amp;690\" src=\"http://s6.sinaimg.cn/bmiddle/5f18712dg779ea3406d45?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\">柏林墙的倒塌</font></strong>（一名西德人在用大锤猛击柏林墙，柏林墙的倒塌为东西德国统一铺平了道路。）</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s2.sinaimg.cn/orignal/5f18712dg779f3d737931&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"15\" real_src=\"http://s2.sinaimg.cn/bmiddle/5f18712dg779f3d737931&amp;690\" src=\"http://s2.sinaimg.cn/bmiddle/5f18712dg779f3d737931?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; max-width: 500px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" /></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">奔向自由</strong><font style=\"font-size: 14px\">（</font><font style=\"font-size: 14px\">1989年11月10日，东柏林疯狂的居民奔向自由的西柏林。）</font></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a href=\"http://photo.blog.sina.com.cn/showpic.html#blogid=5f18712d0100fjl9&amp;url=http://s1.sinaimg.cn/orignal/5f18712dg779f4bfe96d0&amp;690\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"飞跃柏林墙\" data-=\"\" data-img-idx=\"16\" height=\"300\" real_src=\"http://s1.sinaimg.cn/bmiddle/5f18712dg779f4bfe96d0&amp;690\" src=\"http://s1.sinaimg.cn/bmiddle/5f18712dg779f4bfe96d0?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 476px; padding-right: 0px; max-width: 500px; height: 315px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" title=\"飞跃柏林墙\" width=\"475\" /></a></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">反思</strong><font style=\"font-size: 14px\">（</font></font><font style=\"font-size: 14px\">柏林市民在柏林墙的缝隙间插上鲜花纪念逝去的人们。）</font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-family: 楷体_GB2312, 楷体; font-size: 22px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">巳已己曰：</strong></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font style=\"font-size: 22px\"><font style=\"font-family: 黑体\"><font style=\"font-family: 隶书\"><font style=\"font-family: 楷体_GB2312, 楷体\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; 十一月三号，德国总理默克尔与美国总统奥巴马在白宫举行了会晤，并做了被视为过去五十年来德国总理首次在美国国会演讲的历史性演说。她这样说道：<font color=\"#ff0000\">&ldquo;柏林的自由之钟，正如费城的自由钟，是提醒我们自由不是从天上掉下来的标志，而必须透过奋斗而来，并在我们的生命中日日维护。&rdquo;</font>德国人通过他们自己的奋斗争取到了自由，<font style=\"font-size: 22px\">柏林墙终在1989年<font size=\"4\"><font style=\"font-size: 22px\">11月9日倒在了</font><font style=\"font-size: 22px\">人们的喜悦之中轰然倒塌，而类似的悲剧却并没有在这里地球上结束，二十年了，在远隔德国万里重洋的另外一个国家，依旧有一堵用来对付自己的百姓的墙巍峨耸立着。他们之间唯一的区别是：<font color=\"#ff0000\">大多数人看不到甚至不知道有这堵墙的存在。</font></font></font></font></strong></font></font></font></font></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">摘录几段《飞跃柏林墙》的文字</strong></span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; 柏林墙工程的代号，就是&ldquo;中国长城第二&rdquo;。</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; 历史记载，柏林墙初步完成，即东西柏林正式分割，在1961年8月13日中午12点37分，最后一个路口宣布封锁为标志。但就在13日，最早明白过来的东德人已经开始用生命搏击柏林墙，当天，一位技工跨过正在树立的铁丝网跳进了西柏林，有人跳进运河游到了西柏林。然而，天意弄人，谁也没想到记录他们踏上西德领土的时间。<br />\r\n				&nbsp;&nbsp;&nbsp; 13日上午，西德人涌向柏林墙，向墙那边的同胞投掷自己的通行证，身份证件。到苏联军队能够阻止这一举动前，数以千计的证件已经被扔到了东德同胞的手里。大批东德人借机混在返回西柏林的西德人中间偷渡逾越了柏林墙。<br />\r\n				&nbsp;&nbsp;&nbsp; 13日下午，柏林墙树立以后，第一个逾越柏林墙的人出现了。一个青年在光天化日之下，用百米冲刺的速度飞奔向铁丝网。但是，三名警察追上了他，将他打倒在地，谁也没有想到，被打倒的他竟奇迹般又站了起来，夺过警察的枪，一边与警察对峙一边继续向西柏林飞奔。警察是尽职的，他们不顾这个年轻人的枪，冲上去和他又一次扭打成一团，并且一刀刺进青年人的膝盖。这次这个年轻人失去了奔跑的能力，面对三个警察，结局已经注定。<br />\r\n				&nbsp;&nbsp;&nbsp;&nbsp; 然而，上天决心要给大家看一幕喜剧而不是悲剧。就在此刻，西柏林群众雷鸣般的怒吼惊醒了三名警察，他们已经越过了柏林墙，现在是在西德的土地上，他们不再是警察，而成了违法者。他们扔下青年跑回柏林墙的另一侧。这个青年拖著残废的腿，一边拼命呼救一边爬到了西柏林。</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&hellip;&hellip;&nbsp;</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp; 1968年，一位东德青年利用河流潜水到达西德。大家心目中的潜水是什么样的？潜水服？潜水镜？总之他一个人能有多大本事，还一切都必须自己造，最多是一点粗糙的个人潜水工具罢？非也，这位青年自己造的是&mdash;&mdash;潜 - 水 - 艇！他用的是摩托车马达，配上自己组装的钢板，还有导航，压缩气体等系统。硬是在家造出了一个个人用的小潜水艇。质量如何？我看可以通过ISO9002国际认证。这潜水艇在水下航行了超过5个小时，才从西德那边冒出来，其中没有发生任何事故。有同学说了，5个小时是不是太长了一点？那是没办法的事情，你试试拿个小摩托的马达去潜水看看。这小潜水艇当然是一个奇迹，该青年的逃亡过程使他立刻在西德找到了工作，各大机械公司竞相聘用该青年为设计师。听说后来他还真在机械设计上大有成就。</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&hellip;&hellip;</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; 1979年某夜晚，从东德一个家庭的后院升起了一个巨大的热气球。气球下面的吊篮里装著两个家庭&mdash;&mdash;两对夫妇和他们的四个孩子。这个气球完全由这两个家庭手工制成，花了数年的时间。在此期间，两个家庭自学成才，从材料学，工程学，气体动力学，气象学&hellip;&hellip;一直到建立家庭实验室，最后成功的在家庭的后院里制作完成了这个高达28米的热气球！经调查，此热气球是欧洲历史上最大的热气球，被记入吉尼斯世界记录！<br />\r\n				&nbsp;&nbsp;&nbsp; 这个热气球在通过柏林墙的时候，被警察发现了。警察目瞪口呆之余，还算记得开枪射击。这一射击，该气球良好的工艺水准就发挥了出来。逃亡者操纵热气球一下升高到了2800米以上的高空，不但枪打不到，连探照灯都照不到！警察只好紧急呼叫空军支援：&ldquo;长江长江，我是黄河，你们赶快出动，寻找一个热气球，把它打下来。对！没错！是热气球！重复一遍，热 - 气 - 球！&rdquo;<br />\r\n				&nbsp;&nbsp;&nbsp; 苏联空军的&ldquo;苏&rdquo;、&ldquo;米&rdquo;战机立刻出动，但是热气球在28分钟的飞行以后，已经完成了使命，安全落地。问题是，当气球被发现以后，两家人决定立刻降落，以避免被战机击落。这一&ldquo;紧急降落&rdquo;，就谁也摸不准方向了&mdash;&mdash;降落的地点无法确定。到底是已经到了西德，还是被迫降在东德，谁也不知道。<br />\r\n				&nbsp;&nbsp;&nbsp; 估计在他们数年的学习中没有心理学的功课，面对未知的前景，8个人都失去了验证的勇气。他们根本不敢走出这个气球，就这样躲在吊篮里长达24小时之久。他们已经没有勇气亲自揭晓自己的命运了。他们唯一能做的，就是祈祷。降落整整24小时以后，军人来了，揭开了气球。他们对这8个逃亡者说出了他们盼望了多少年的话。&mdash;&mdash;&ldquo;你们自由了，这里是西德领土。&rdquo;</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&hellip;&hellip;</span></p>\r\n			<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; 凡靠近柏林墙的高楼，都成了东德人&ldquo;跳楼&rdquo;的场所。不必担心，这里的跳楼可不是求死，而是求生。只要你爬到楼上，表现出逃亡的意图，西柏林的同胞们就抬著床单蜂拥前来接应。鼓足勇气，一跃而下，只要把握了方向，就可以在空中逾越柏林墙，落到床单上。<br />\r\n				&nbsp;&nbsp;&nbsp; 当然，不是每个人都有这么高的运动天份的。曾经有一家三口一起跳楼。6岁的孩子成功了，父亲和母亲却摔到了地面，一个伤了内脏，一个伤了脊椎。在短短的跳楼时代，有4个人因跳楼而死亡。<br />\r\n				年纪最大的跳楼者是一位77岁的老太太。她在跳下来之前，把自己吓得瘫倒在了地板上。无论大家怎么鼓励，怎么哀求也无法跳下来。就在西柏林人准备失望的散去的时候，一个意外发生了。东柏林的警察发现了情况，冲进了大楼。警察破门的声音给了老太太无穷的动力，她冲向窗口，果断的一跃而下&hellip;&hellip;</span></p>\r\n			<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;</span></div>\r\n	</div>\r\n</div>\r\n<p>\r\n	&nbsp;</p>\r\n', '0', '1', '1', '2016-09-28 09:01:20', null, '0');
INSERT INTO `entry` VALUES ('226', '76', '柏林墙的老照片 2014-1-30 19:47 阅读(0)', '<p>\r\n	&nbsp;</p>\r\n<table cellpadding=\"0\" cellspacing=\"0\" id=\"blogContentTable\" style=\"position: relative; padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px; padding-left: 0px; border-spacing: 0px; width: 880px; padding-right: 0px; border-collapse: collapse; font: 12px/19px punctuation, 微软雅黑, Tohoma; white-space: normal; table-layout: fixed; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<tbody style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n		<tr style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n			<td style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; word-wrap: break-word; padding-top: 0px\" valign=\"top\">\r\n				<div id=\"blogContainer\" style=\"position: relative; padding-bottom: 0px; margin: 0px; padding-left: 16px; padding-right: 16px; height: 10491px; overflow: hidden; padding-top: 0px\">\r\n					<div align=\"center\" class=\"lp_title_type_3\" id=\"paperTitleArea\" style=\"background-image: url(/qzone/space_item/orig/9/81177_t5.gif); padding-bottom: 0px; margin: 0px 0px 35px 72px; padding-left: 0px; width: 690px; padding-right: 0px; background-repeat: no-repeat; background-position: 50% 50%; height: 70px; padding-top: 0px\">\r\n						<span id=\"paperTitle\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; display: block; color: rgb(0,0,0); word-break: break-all; padding-top: 25px\"><font color=\"#000000\" face=\"微软雅黑\" style=\"font-size: 26px\">柏林墙的老照片</font></span></div>\r\n					<div data-webp-ctx-e=\"1\" id=\"blogDetailDiv\" style=\"padding-bottom: 0px; margin: 0px; min-height: 380px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); font-size: 14px; padding-top: 0px\">\r\n						<div class=\"blog_details_20120222\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n							<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n								&nbsp;<a href=\"http://bbs.voc.com.cn/topic-241352-1-1.html\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\">http://bbs.voc.com.cn/topic-241352-1-1.html<br />\r\n								<br />\r\n								<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;</span></a><br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									简易围墙</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613021.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"0\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613021.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									第二次世界大战结束后，德国被分为4个区域，分别由法国、英国、美国和苏联接管，后来前三方合并，而苏联接管的地区变得更加孤立。这条1953年拉起的钢丝围栏把很多德国朋友分开了<br />\r\n									　　<br />\r\n									　　1987年6月12日清晨，美国总统里根抵达柏林，此时这座城市正在庆贺其750岁诞辰。在将东西柏林割裂数年的分界线&mdash;&mdash;勃兰登堡门的柏林墙前，里根发表了著名的发表演讲。演讲稿由秘书起草，听者主要是正意欲与美国缔结友好关系的对象&mdash;&mdash;苏联领导人米哈伊尔&middot;戈尔巴乔夫，还有届时在场的2万名听众。<br />\r\n									　　<br />\r\n									　　在这次著名的演讲中，里根呼吁戈尔巴乔夫拆掉柏林墙，这一言辞遭到美国国务院和国家安全委员会的强烈反对，他们担心克里姆林宫的强硬派会以此向戈氏提出质疑。那天下午，不到2时，里根走上讲台。因为担心会有恐怖袭击，里根身后放置了两块巨大的防弹玻璃。<br />\r\n									　　<br />\r\n									　　里根总统说出了以下这段震撼世界的话：&ldquo;戈尔巴乔夫总书记，如果你要寻求和平，如果你要为苏联和东欧寻求繁荣，如果你要寻求自由：就到这扇门来吧！戈尔巴乔夫先生，打开这扇门！戈尔巴乔夫先生，拆掉这堵墙！&rdquo;</center>\r\n								<br />\r\n								　　<br />\r\n								　　<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									砖头&middot;墙</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613022.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"7\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613022.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									随着苏联和西方国家紧张局势的加剧，不同地区间的通道逐渐缩小。1961年，这条边界被正式化地变成了一堵砖墙，照片中东德士兵和工人正在给柏林墙增加高度。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									分隔</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613023.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"14\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613023.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									柏林墙把千千万万的德国家庭分隔开来，许多居住在东部的德国人无法再去西部上班。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									无人之地</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613024.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"21\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613024.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									延墙而行的街道也都被割裂开来，许多交通工具无法再在那里行驶。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									逃离</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613025.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"28\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613025.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									多年来很多东德人试图逃到西边去。图为1961年一名17岁的东德男孩翻越柏林墙，两名西德警察正在帮助他安全地下来。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									悲伤</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613026.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"35\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613026.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									柏林墙建成后，西德变成了一片孤独的、被敌视和被包围的土地。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									关闭</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613027.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"42\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613027.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									在柏林墙位于奥巴鲍姆桥的检查站，两名东德边界警卫锁好大门后离开。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									团结</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613028.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"43\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613028.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									美国总统肯尼迪于1963年访问柏林墙位于勃兰登堡门的关口，他在发表演讲时用德语说：我是一个柏林人(ICH BIN EIN BERLINER)。这句话后来成为名言。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									障碍</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613030.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"50\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613030.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									到上世纪80年代中期，柏林墙已经成为冷战的最持久象征。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									历史性访问</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613031.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"57\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613031.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									1987年6月，美国总统里根访问柏林，从德国国会大厦的阳台上观看柏林墙。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									著名的话语</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613032.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"64\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613032.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									　1987年6月，里根在西柏林勃兰登堡门发表演说，在提到戈尔巴乔夫时说了一句话：&ldquo;戈尔巴乔夫先生，拆掉这堵墙吧。&rdquo;</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									峰会</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613033.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"71\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613033.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									　1987年，里根和戈尔巴乔夫在美国首都华盛顿会晤。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									不再分离</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613034.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"78\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613034.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									1989年11月9日，东德领导人埃根&middot;克伦兹批准了&ldquo;迁徙自由的新旅行法&rdquo;，千千万万民众潮水般地涌向西柏林。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									　柏林墙的倒塌</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613035.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"85\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613035.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									一名西德人在用大锤猛击柏林墙，柏林墙的倒塌为东西德国统一铺平了道路。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									自由</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; background: none transparent scroll repeat 0% 0%; padding-top: 0px\">\r\n										<a href=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613036.jpg\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"按此在新窗口浏览图片\" border=\"0\" data-=\"\" data-img-idx=\"92\" src=\"http://gb.cri.cn/mmsource/images/2007/06/13/nz070613036.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></a></div>\r\n								</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									东西德国人的手一起拉下了柏林墙上的铁丝网。</center>\r\n								<br />\r\n								　　<br />\r\n								　　\r\n								<center style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<img data-=\"\" data-img-idx=\"99\" src=\"http://qqadapt.qpic.cn/adapt/0/cd2b93b7-a8a1-ae7d-036d-9423bd012550/800?pt=0&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></center>\r\n								<br />\r\n								　　<br />\r\n								　　<br />\r\n								　　<br />\r\n								　　<br />\r\n								<br />\r\n								<font color=\"#d3d3d3\">[此贴子已经被作者于2007-6-13 21:19:58编辑过]</font><br />\r\n								&nbsp;</div>\r\n						</div>\r\n					</div>\r\n				</div>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<br class=\"Apple-interchange-newline\" />\r\n', '0', '1', '1', '2016-09-28 09:01:46', null, '0');
INSERT INTO `entry` VALUES ('227', '76', '柏林墙下的血泪逃亡史 2014-1-30 19:46 阅读(0)', '<p>\r\n	&nbsp;</p>\r\n<table cellpadding=\"0\" cellspacing=\"0\" id=\"blogContentTable\" style=\"position: relative; padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px; padding-left: 0px; border-spacing: 0px; width: 880px; padding-right: 0px; border-collapse: collapse; font: 12px/19px punctuation, 微软雅黑, Tohoma; white-space: normal; table-layout: fixed; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<tbody style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n		<tr style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n			<td style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; word-wrap: break-word; padding-top: 0px\" valign=\"top\">\r\n				<div id=\"blogContainer\" style=\"position: relative; padding-bottom: 0px; margin: 0px; padding-left: 16px; padding-right: 16px; height: 1555px; overflow: hidden; padding-top: 0px\">\r\n					<div align=\"center\" class=\"lp_title_type_3\" id=\"paperTitleArea\" style=\"background-image: url(/qzone/space_item/orig/9/81177_t5.gif); padding-bottom: 0px; margin: 0px 0px 35px 72px; padding-left: 0px; width: 690px; padding-right: 0px; background-repeat: no-repeat; background-position: 50% 50%; height: 70px; padding-top: 0px\">\r\n						<span id=\"paperTitle\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; display: block; color: rgb(0,0,0); word-break: break-all; padding-top: 25px\"><font color=\"#000000\" face=\"微软雅黑\" style=\"font-size: 26px\">柏林墙下的血泪逃亡史</font></span></div>\r\n					<div data-webp-ctx-e=\"1\" id=\"blogDetailDiv\" style=\"padding-bottom: 0px; margin: 0px; min-height: 380px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); font-size: 14px; padding-top: 0px\">\r\n						<div class=\"blog_details_20120222\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n							<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n								&nbsp;<a href=\"http://www.360doc.com/resaveArt.aspx?articleid=8418063&amp;isreg=1\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\">http://www.360doc.com/resaveArt.aspx?articleid=8418063&amp;isreg=1</a>&nbsp;<br />\r\n								<br />\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 100px; padding-right: 0px; padding-top: 0px\"><a href=\"http://www.stnn.cc/\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\">星岛环球网 www.stnn.cc</a></span><span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 80px; padding-right: 0px; padding-top: 0px\">2009-11-04</span></span></div>\r\n								<p align=\"center\" style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><img data-=\"\" data-img-idx=\"0\" oldsrc=\"W020091103417421192133.jpg\" src=\"http://image4.360doc.com/DownloadImg/2009/11/5/19446_8418063_1.jpg?pt=5&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></span></p>\r\n								<p align=\"center\" style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">东德士兵越过柏林墙投奔西德</span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">　　美国《国家地理》杂志社记者彼德列宾拍摄的这张流传极广的照片成为20世纪人类政治历史的重要见证之一。在所有关于这张照片的解说中，这段文字是最为简洁的：&ldquo;1961年8月13日凌晨，在铁丝网网成的柏林墙即将封闭的一瞬间，一个参与围墙行动的东德士兵突然跃过铁丝网，投奔西德一方。&rdquo;然而，在其背后所凝聚的历史风云和血泪故事之复杂与惨烈实远非笔墨所能形容。</span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">　　从1949年起至1961年8月13日止，逃往西德的东德人多达260多万，约占当时东德总人口的八分之一。不允许人民用手投票的政权往往也不允许人民用脚投票。1961年8月12日晚10时，在德国统一社会党总书记乌布利希在他的别墅里宣布了建柏林墙的决定，他说：&ldquo;为了社会主义，我们必须这样做。&rdquo;</span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">　　8月13日1时，东德国家人民军、警察部队和工人战斗队开始行动，一辆辆军车把士兵和铁丝网运到了工作地点。在夜幕的掩护下，士兵们在路面上钻孔、竖水泥柱然后架设带刺的铁丝网。黎明时分，一条蜿蜒于街道、住宅区、花园，横贯164公里边界线上的铁丝网建成了。</span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">　　照片中的士兵是黎明中历史性的一跃。</span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 1em 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">　　据记载，最终完成的柏林墙全长170多公里，将柏林市192条大街一分为二。墙平均高4．2米，由水泥浇筑而成。柏林墙共有前后两道，其间留有100米宽的无人区巡逻通道，通道内设有防汽车壕、反坦克路障、电网、地雷、自动射击装置等，还设有无数望塔、地堡、警犬桩等设施，对强行闯关者可当场击毙。</span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">　　1963年6月25日，美国总统肯尼迪在西柏林发表演讲说：&ldquo;自由困难重重，民主并不完美，但是我们从来没有垒起一堵墙，把人民挡在其中，阻止他们逃离我们。&rdquo;他认为，&ldquo;这是人类历史上第一堵不是防范外敌，而是防范自己人民的墙。&rdquo;</span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;</span></p>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">　　在这张照片中的士兵跳跃之后的后继者们，只能选择跳楼、以重型机动车辆撞墙、翻墙、小汽车钻栏杆、开潜水艇、爬电缆卷筒、挖地下隧道、乘空中热气球等方式逃亡。<br />\r\n									有统计说，在柏林墙存在的28年岁月里，共有5043人成功越墙逃入西柏林，239人死亡，260人受伤。此外还有约六万人被指控为&ldquo;企图叛逃&rdquo;而遭到为期平均十六个月的监禁。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">1989年11月9日，在宣布民德公民可以自由穿越柏林墙的那个晚上，约10万人像潮水一般从柏林墙的东边涌向西边，并动手拆除柏林墙。到了晚上10点半，横亘在东西柏林间长达29年的这道现代&ldquo;长城&rdquo;被凿出了一个大洞，人们心中的柏林墙就此倒掉。西柏林政府向涌入的东德兄弟奉上了丰厚的见面礼，除了泪水、拥抱、亲吻和鲜花水果，还有每人100马克的欢迎费。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">德国作家彼得&middot;施奈德在一篇文章中写道，&ldquo;清除大脑中的柏林墙将花上比清除实体上的柏林墙长得多的时间。&rdquo;</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">柏林墙见证了德国的分裂与统一，经历了冷战的风雨洗礼。尽管已成历史，但这座城市却处处留有它的遗迹，仿佛在诉说着当年东西分隔的血泪历史。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">柏林墙建成后，西德变成了一片孤独的、被敌视和被包围的土地。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">多年来很多东德人试图逃到西边去。图为1961年一名17岁的东德男孩翻越柏林墙，两名西德警察正在帮助他安全地下来。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">延墙而行的街道也都被割裂开来，许多交通工具无法再在那里行驶</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">柏林墙把千千万万的德国家庭分隔开来，许多居住在东部的德国人无法再去西部上班</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">随着苏联和西方国家紧张局势的加剧，不同地区间的通道逐渐缩小。1961年，这条边界被正式化地变成了一堵砖墙，照片中东德士兵和工人正在给柏林墙增加高度。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">为了遏制东德人逃入西柏林的趋势，东德政府从1961年8月13日开始修建柏林墙。东西柏林之间本来只是铁丝隔离网，后来才大量换成真正的墙。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">到上世纪80年代中期，柏林墙已经成为冷战的最持久象征。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">美国总统肯尼迪于1963年访问柏林墙位于勃兰登堡门的关口，他在发表演讲时用德语说：我是一个柏林人(ICH BIN EIN BERLINER)。这句话后来成为名言。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">1987年6月，美国总统里根访问柏林，从德国国会大厦的阳台上观看柏林墙。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">1987年6月，里根在西柏林勃兰登堡门发表演说，他说出了这段震撼世界的话：&ldquo;戈尔巴乔夫总书记，如果你要寻求和平，如果你要为苏联和东欧寻求繁荣，如果你要寻求自由：就到这扇门来吧！戈尔巴乔夫先生，打开这扇门！戈尔巴乔夫先生，拆掉这堵墙！&rdquo;</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">随着冷战进入尾声，东西方关系开始缓和。1987年，里根和戈尔巴乔夫在美国首都华盛顿会晤。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">1989年11月9日，新东德政府开始计划放松对东德人民的旅游限制，但由于当时的东德中央政治局委员G&uuml;nter Achabowski对上级命令的误解，错误地宣布柏林墙即将开放，导致数以万计的市民走上街头，拆毁围墙。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">东德领导人批准了&ldquo;迁徙自由的新旅行法&rdquo;，千千万万民众潮水般地涌向西柏林。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">一名西德人在用大锤猛击柏林墙，柏林墙的倒塌为东西德国统一铺平了道路。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">东西德国人的手一起拉下了柏林墙上的铁丝网。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">如今在柏林，十几年前被拆除的柏林墙已经变成了一道贯穿旧城20公里长的鹅卵石小径，当年戒备森严的哨所已经成了旅游景点。</span></div>\r\n								<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">柏林墙的修建是东西方两大阵营意识形态斗争的产物，东德人称柏林墙为&ldquo;反法西斯防卫墙&rdquo;，西德人则认为柏林墙隔断了自由与民主。它见证了德国的分裂与统一，经历了冷战的风雨洗礼。尽管这一切都已成历史，但这座城市却处处留有它的遗迹，无论是现实还是心理上。<strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">来源：淮安生活网</strong></span></div>\r\n								<p style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">　　</span></p>\r\n								<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;</span></div>\r\n						</div>\r\n					</div>\r\n				</div>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<br class=\"Apple-interchange-newline\" />\r\n', '0', '1', '1', '2016-09-28 09:02:05', null, '0');
INSERT INTO `entry` VALUES ('228', '76', '翻越柏林墙的男孩 2014-1-30 19:43 阅读(0)', '<p>\r\n	&nbsp;</p>\r\n<table cellpadding=\"0\" cellspacing=\"0\" id=\"blogContentTable\" style=\"position: relative; padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px; padding-left: 0px; border-spacing: 0px; width: 880px; padding-right: 0px; border-collapse: collapse; font: 12px/19px punctuation, 微软雅黑, Tohoma; white-space: normal; table-layout: fixed; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<tbody style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n		<tr style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n			<td style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; word-wrap: break-word; padding-top: 0px\" valign=\"top\">\r\n				<div id=\"blogContainer\" style=\"position: relative; padding-bottom: 0px; margin: 0px; padding-left: 16px; padding-right: 16px; height: 677px; overflow: hidden; padding-top: 0px\">\r\n					<div align=\"center\" class=\"lp_title_type_3\" id=\"paperTitleArea\" style=\"background-image: url(/qzone/space_item/orig/9/81177_t5.gif); padding-bottom: 0px; margin: 0px 0px 35px 72px; padding-left: 0px; width: 690px; padding-right: 0px; background-repeat: no-repeat; background-position: 50% 50%; height: 70px; padding-top: 0px\">\r\n						<span id=\"paperTitle\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; display: block; color: rgb(0,0,0); word-break: break-all; padding-top: 25px\"><font color=\"#000000\" face=\"微软雅黑\" style=\"font-size: 26px\">翻越柏林墙的男孩</font></span></div>\r\n					<div data-webp-ctx-e=\"1\" id=\"blogDetailDiv\" style=\"padding-bottom: 0px; margin: 0px; min-height: 380px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); font-size: 14px; pad