INSERT INTO `entry` VALUES ('274', '76', '微服私访：还说自己不是奴才？ 2013-4-18 14:58 阅读(0)', '<p>\r\n	&nbsp;</p>\r\n<table cellpadding=\"0\" cellspacing=\"0\" id=\"blogContentTable\" style=\"position: relative; padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px; padding-left: 0px; border-spacing: 0px; width: 880px; padding-right: 0px; border-collapse: collapse; font: 12px/19px punctuation, 微软雅黑, Tohoma; white-space: normal; table-layout: fixed; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<tbody style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n		<tr style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n			<td style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; word-wrap: break-word; padding-top: 0px\" valign=\"top\">\r\n				<div id=\"blogContainer\" style=\"position: relative; padding-bottom: 0px; margin: 0px; padding-left: 16px; padding-right: 16px; height: 1132px; overflow: hidden; padding-top: 0px\">\r\n					<div align=\"center\" class=\"lp_title_type_3\" id=\"paperTitleArea\" style=\"background-image: url(/qzone/space_item/orig/9/81177_t5.gif); padding-bottom: 0px; margin: 0px 0px 35px 72px; padding-left: 0px; width: 690px; padding-right: 0px; background-repeat: no-repeat; background-position: 50% 50%; height: 70px; padding-top: 0px\">\r\n						<span id=\"paperTitle\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; display: block; color: rgb(0,0,0); word-break: break-all; padding-top: 25px\"><font color=\"#000000\" face=\"微软雅黑\" style=\"font-size: 26px\">微服私访：还说自己不是奴才？</font></span></div>\r\n					<div data-webp-ctx-e=\"1\" id=\"blogDetailDiv\" style=\"padding-bottom: 0px; margin: 0px; min-height: 380px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); font-size: 14px; padding-top: 0px\">\r\n						<div class=\"blog_details_20120222\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n							<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n								<img alt=\"图片\" data-=\"\" data-img-idx=\"0\" src=\"http://b254.photo.store.qq.com/psb?/V148TWI01v1rR9/sw6c8XhWygtORlgIKZVs802yJnkcqYHxOaKH9uf83jI!/b/dHEKcJeMFwAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;bo=LAEuAAAAAAABACQ!&amp;t=5&amp;su=0111233729&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 564px; padding-right: 0px; height: 152px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /><br />\r\n								<br />\r\n								<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-family: 楷体, 楷体_GB2312; font-size: 18px; padding-top: 0px\">实际上是奴隶、中国的廉价劳动力. . . . . .<br />\r\n								&ldquo;劳动力的价值，是由生产、发展、维持和延续劳动力所必需的生活必需品的价值决定的。&rdquo;<br />\r\n								由于劳动力价值的构成包含着一个<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(255,0,0); padding-top: 0px\">历史的和道德的</span>因素，在<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(255,0,0); padding-top: 0px\">不同的国家或在同一国家的不同历史时期</span>，劳动者所必需的生活资料的数量和构成也是有区别的，所以劳动力价值的最低界限，是由生活上不可缺少的生活资料的价值决定的。</span><br />\r\n								<br />\r\n								<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><img alt=\"图片\" data-=\"\" data-img-idx=\"1\" src=\"http://b253.photo.store.qq.com/psb?/V148TWI01v1rR9/NqqGPMIyUUODM0j6ppRm.Bbuo27JmtAaz9Kq9lcvT9I!/b/dJMM2ZYcFAAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;bo=IAM3AgAAAAABADE!&amp;t=5&amp;su=0201492113&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 800px; padding-right: 0px; height: 567px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" />&nbsp;<br />\r\n								<br />\r\n								<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;绝对不会成为中国的廉价劳动力~~~</span></span></div>\r\n						</div>\r\n					</div>\r\n				</div>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<br class=\"Apple-interchange-newline\" />\r\n', '0', '1', '1', '2016-09-28 09:19:18', null, '0');
