INSERT INTO `entry` VALUES ('279', '76', 'Java Stack&Queue 2013-4-13 00:26 阅读(0)', '<p>\r\n	&nbsp;</p>\r\n<table cellpadding=\"0\" cellspacing=\"0\" id=\"blogContentTable\" style=\"position: relative; padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px; padding-left: 0px; border-spacing: 0px; width: 880px; padding-right: 0px; border-collapse: collapse; font: 12px/19px punctuation, 微软雅黑, Tohoma; white-space: normal; table-layout: fixed; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<tbody style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n		<tr style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n			<td style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; word-wrap: break-word; padding-top: 0px\" valign=\"top\">\r\n				<div id=\"blogContainer\" style=\"position: relative; padding-bottom: 0px; margin: 0px; padding-left: 16px; padding-right: 16px; height: 1744px; overflow: hidden; padding-top: 0px\">\r\n					<div align=\"center\" class=\"lp_title_type_3\" id=\"paperTitleArea\" style=\"background-image: url(/qzone/space_item/orig/9/81177_t5.gif); padding-bottom: 0px; margin: 0px 0px 35px 72px; padding-left: 0px; width: 690px; padding-right: 0px; background-repeat: no-repeat; background-position: 50% 50%; height: 70px; padding-top: 0px\">\r\n						<span id=\"paperTitle\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; display: block; color: rgb(0,0,0); word-break: break-all; padding-top: 25px\"><font color=\"#000000\" face=\"微软雅黑\" style=\"font-size: 26px\">Java Stack&amp;Queue</font></span></div>\r\n					<div data-webp-ctx-e=\"1\" id=\"blogDetailDiv\" style=\"padding-bottom: 0px; margin: 0px; min-height: 380px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); font-size: 14px; padding-top: 0px\">\r\n						<div class=\"blog_details_20120222\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n							<div style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(255,0,0); font-size: 18px; padding-top: 0px\">import java.util.Stack;</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">public class</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">stack</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">{</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">public static void main(String[] args)</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">{</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(255,0,0); padding-top: 0px\"><span class=\"Apple-converted-space\">&nbsp;</span></span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(255,0,0); font-size: 18px; padding-top: 0px\">Stack s = new Stack();</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(255,0,0); padding-top: 0px\">&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(255,0,0); font-size: 18px; padding-top: 0px\">s.push(&quot;ToT&quot;);</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">s.push(3.14);</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">s.push(&quot;orz&quot;);</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">System.out.println(s);</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">System.out.println(&quot;<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(255,0,0); padding-top: 0px\">s.pop()<span class=\"Apple-converted-space\">&nbsp;</span></span>=<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); padding-top: 0px\">&quot;+</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); padding-top: 0px\">s.pop());</span></span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">System.out.println(&quot;<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(255,0,0); padding-top: 0px\">s.size()</span><span class=\"Apple-converted-space\">&nbsp;</span>= &quot;+s.size());</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">System.out.println(&quot;<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(255,0,0); padding-top: 0px\">s.search(new Double(3.14))<span class=\"Apple-converted-space\">&nbsp;</span></span>= &quot;+s.search(new Double(3.14)));</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">System.out.println(&quot;<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(255,0,0); padding-top: 0px\">s.empty()<span class=\"Apple-converted-space\">&nbsp;</span></span>= &quot;+s.empty());</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(255,0,0); font-size: 18px; padding-top: 0px\">s.clear();</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">System.out.println(&quot;s.clear() : &quot;+s);</span></font></span></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0cm 0cm 0pt; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><font face=\"Times New Roman\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 18px; padding-top: 0px\">}</sp