INSERT INTO `entry` VALUES ('313', '76', 'main函数的参数 2012-5-19 11:55 阅读(0)', '<div class=\"blog_cont\" style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font: 12px/19px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); overflow: hidden; word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<div class=\"blog_cont_details\" id=\"veryContent\" style=\"padding-bottom: 0px; margin: 10px 0px; padding-left: 0px; padding-right: 0px; height: auto !important; padding-top: 0px\">\r\n		<table cellpadding=\"0\" cellspacing=\"0\" id=\"blogContentTable\" style=\"position: relative; padding-bottom: 0px; margin: 0px; padding-left: 0px; border-spacing: 0px; width: 880px; padding-right: 0px; border-collapse: collapse; table-layout: fixed; padding-top: 0px\">\r\n			<tbody style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<tr style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n					<td style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; word-wrap: break-word; padding-top: 0px\" valign=\"top\">\r\n						<div id=\"blogContainer\" style=\"position: relative; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; height: 1130px; overflow: hidden; padding-top: 0px\">\r\n							<div data-webp-ctx-e=\"1\" id=\"blogDetailDiv\" style=\"padding-bottom: 0px; margin: 0px; min-height: 380px; padding-left: 0px; padding-right: 0px; font-size: 14px; padding-top: 0px\">\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									/*&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 1.cpp&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; */&nbsp;</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									&nbsp;</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									#include &lt;stdio.h&gt;</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									int main(int argc,char **argv)</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									{<br />\r\n									&nbsp;&nbsp;&nbsp; freopen(argv[1],&quot;r&quot;,stdin);<br />\r\n									&nbsp;&nbsp;&nbsp; printf(&quot;参数个数：%d\\n&quot;, argc);<br />\r\n									&nbsp;&nbsp;&nbsp; printf(&quot;第一个参数：%s\\n&quot;, argv[0]);<br />\r\n									&nbsp;&nbsp;&nbsp; printf(&quot;第二个参数：%s\\n&quot;, argv[1]);<br />\r\n									&nbsp;<br />\r\n									&nbsp;&nbsp;&nbsp; int a,b;<br />\r\n									&nbsp;&nbsp;&nbsp; scanf(&quot;%d%d&quot;,&amp;a,&amp;b);<br />\r\n									&nbsp;&nbsp;&nbsp; printf(&quot;\\n%d + %d = %d\\n&quot;,a,b,a+b);</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									}</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									&nbsp;</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									**************************************************************************</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									&nbsp;</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<a appendurl=\"1\" href=\"http://b87.photo.store.qq.com/psb?/0ff3b503-fc11-4a63-94de-468a6004ab32/eeIEjOXSKssCjYPhIHEskHhTcE0OtlD4QBcjFHmFcxU!/b/Ye3L3zNPTgAAYlTX4jO*TwAA\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"图片\" appendurl=\"1\" data-=\"\" data-img-idx=\"0\" height=\"94\" src=\"http://b87.photo.store.qq.com/psb?/0ff3b503-fc11-4a63-94de-468a6004ab32/eeIEjOXSKssCjYPhIHEskHhTcE0OtlD4QBcjFHmFcxU!/b/Ye3L3zNPTgAAYlTX4jO*TwAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;t=5&amp;su=0139410737&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" width=\"318\" /></a></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									&nbsp;</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									**************************************************************************</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<br />\r\n									<a appendurl=\"1\" href=\"http://b87.photo.store.qq.com/psb?/0ff3b503-fc11-4a63-94de-468a6004ab32/YLB8MhuwL966E0*fJQqB7DxfXY2HvLLX.DiNcmD5Mhk!/b/YfXt6DNNTwAAYqJY5DPCTgAA\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"图片\" appendurl=\"1\" data-=\"\" data-img-idx=\"1\" height=\"174\" src=\"http://b87.photo.store.qq.com/psb?/0ff3b503-fc11-4a63-94de-468a6004ab32/YLB8MhuwL966E0*fJQqB7DxfXY2HvLLX.DiNcmD5Mhk!/b/YfXt6DNNTwAAYqJY5DPCTgAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;t=5&amp;su=0179800449&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" width=\"299\" /></a></p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									&nbsp;</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									**************************************************************************</p>\r\n								<p style=\"padding-bottom: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n									<br />\r\n									<a appendurl=\"1\" href=\"http://b85.photo.store.qq.com/psb?/0ff3b503-fc11-4a63-94de-468a6004ab32/dkU04oIoD3su.R6t4STqkbYuQiwGsMiJPa462FJ6V9w!/b/YRshszIugAAAYhuSqzLrfgAA\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><img alt=\"图片\" appendurl=\"1\" data-=\"\" data-img-idx=\"2\" height=\"178\" src=\"http://b85.photo.store.qq.com/psb?/0ff3b503-fc11-4a63-94de-468a6004ab32/dkU04oIoD3su.R6t4STqkbYuQiwGsMiJPa462FJ6V9w!/b/YRshszIugAAAYhuSqzLrfgAA&amp;ek=1&amp;kp=1&amp;pt=0&amp;t=5&amp;su=057153649&amp;sce=0-12-12&amp;rf=2-9\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" width=\"372\" /></a><br />\r\n									**************************************************************************</p>\r\n							</div>\r\n						</div>\r\n					</td>\r\n				</tr>\r\n			</tbody>\r\n		</table>\r\n		<div class=\"clear\" id=\"paperBottom\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n			&nbsp;</div>\r\n	</div>\r\n</div>\r\n<div class=\"blog_footer\" style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font: 12px/19px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<div class=\"operate_toolbar\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n		<div class=\"mod_interactive\" style=\"padding-bottom: 5px; margin: 0px; min-height: 30px; padding-left: 0px; padding-right: 0px; float: left; padding-top: 5px\">\r\n			<ul id=\"footerInteractive\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">\r\n				<li __ugclikebtnid=\"390\" class=\"adjust_praise\" id=\"footerLike\" style=\"padding-bottom: 0px; list-style-type: none; margin: 0px; padding-left: 0px; padding-right: 0px; float: left; height: 23px; list-style-image: none; padding-top: 0px\">\r\n					<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; zoom: 1; display: block; float: left; overflow: hidden; padding-top: 0px\"><a class=\"c_tx rbor3\" href=\"javascript:void(0)\" onclick=\"return false;\" style=\"border-bottom: rgb(224,224,224) 1px; text-align: left; border-left: rgb(224,224,224) 1px; padding-bottom: 5px; line-height: 16px; margin: 0px; padding-left: 0px; padding-right: 10px; display: inline-block; height: 16px; color: rgb(38,112,154); border-top: rgb(224,224,224) 1px; cursor: pointer; border-right: rgb(224,224,224) 1px solid; text-decoration: none; padding-top: 2px\"><span class=\"adjust\" style=\"padding-bottom: 0px; line-height: 16px; margin: 0px; padding-left: 0px; padding-right: 0px; float: left; height: 16px; padding-top: 0px\">赞</span></a></span></li>\r\n				<li id=\"footerReplyInfoArea\" style=\"padding-bottom: 0px; list-style-type: none; margin: 0px; padding-left: 0px; padding-right: 0px; float: left; height: 23px; list-style-image: none; padding-top: 0px\">\r\n					<a class=\"c_tx rbor3\" href=\"javascript:void(0)\" id=\"footerReplyInfoAreaBtn\" onclick=\"return false;\" style=\"border-bottom: rgb(224,224,224) 1px; border-left: rgb(224,224,224) 1px; padding-bottom: 5px; line-height: 16px; margin: 0px; padding-left: 10px; padding-right: 10px; display: inline-block; height: 16px; color: rgb(38,112,154); border-top: rgb(224,224,224) 1px; cursor: pointer; border-right: rgb(224,224,224) 1px solid; text-decoration: none; padding-top: 2px\"><span class=\"adjust\" style=\"padding-bottom: 0px; line-height: 16px; margin: 0px; padding-left: 0px; padding-right: 0px; float: left; height: 16px; padding-top: 0px\">评论</span></a></li>\r\n				<li id=\"footerQuoteInfoArea\" style=\"padding-bottom: 0px; list-style-type: none; margin: 0px; padding-left: 0px; padding-right: 0px; float: left; height: 23px; list-style-image: none; padding-top: 0px\">\r\n					<a class=\"c_tx rbor3\" href=\"javascript:void(0)\" id=\"footerQuoteInfoAreaBtn\" onclick=\"return false;\" style=\"border-bottom: rgb(224,224,224) 1px; border-left: rgb(224,224,224) 1px; padding-bottom: 5px; line-height: 16px; margin: 0px; padding-left: 10px; padding-right: 10px; display: inline-block; height: 16px; color: rgb(38,112,154); border-top: rgb(224,224,224) 1px; cursor: pointer; border-right: rgb(224,224,224) 1px solid; text-decoration: none; padding-top: 2px\"><span class=\"adjust\" style=\"padding-bottom: 0px; line-height: 16px; margin: 0px; padding-left: 0px; padding-right: 0px; float: left; height: 16px; padding-top: 0px\">转载</span></a></li>\r\n				<li id=\"footerShareInfoArea\" style=\"padding-bottom: 0px; list-style-type: none; margin: 0px; padding-left: 0px; padding-right: 0px; float: left; height: 23px; list-style-image: none; padding-top: 0px\">\r\n					<a class=\"c_tx rbor3 drop_list\" href=\"javascript:void(0)\" id=\"footerShareInfoAreaBtn\" onclick=\"return false;\" style=\"border-bottom: rgb(224,224,224) 1px; position: relative; border-left: rgb(224,224,224) 1px; padding-bottom: 5px; line-height: 16px; margin: 0px; padding-left: 10px; padding-right: 30px; display: inline-block; height: 16px; color: rgb(38,112,154); border-top: rgb(224,224,224) 1px; cursor: pointer; border-right: rgb(224,224,224) 1px solid; text-decoration: none; padding-top: 2px\"><span class=\"adjust\" style=\"padding-bottom: 0px; line-height: 16px; margin: 0px; padding-left: 0px; padding-right: 0px; float: left; height: 16px; padding-top: 0px\">分享</span></a></li>\r\n				<li id=\"footerCopyInfoArea\" style=\"padding-bottom: 0px; list-style-type: none; margin: 0px; padding-left: 0px; padding-right: 0px; float: left; height: 23px; list-style-image: none; padding-top: 0px\">\r\n					<span style=\"position: absolute; padding-bottom: 0px; margin: 0px; padding-left: 0px; width: 90px; padding-right: 0px; display: block; background: url(http://qzs.qq.com/ac/b.gif); height: 23px; cursor: pointer; padding-top: 0px\"><object data=\"http://qzs.qq.com/qzone/newblog/v5/flash/flashCopy.swf\" height=\"23\" id=\"_URLCopyBtn\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\" type=\"application/x-shockwave-flash\" width=\"90\"></object></span><a class=\"c_tx rbor3\" href=\"javascript:void(0)\" id=\"footerCopyInfoAreaBtn\" onclick=\"return false;\" style=\"border-bottom: rgb(224,224,224) 1px; border-left: rgb(224,224,224) 1px; padding-bottom: 5px; line-height: 16px; margin: 0px; padding-left: 10px; padding-right: 10px; display: inline-block; height: 16px; color: rgb(38,112,154); border-top: rgb(224,224,224) 1px; cursor: pointer; border-right: rgb(224,224,224) 1px solid; text-decoration: none; padding-top: 2px\"><span class=\"adjust\" style=\"padding-bottom: 0px; line-height: 16px; margin: 0px; padding-left: 0px; padding-right: 0px; float: left; height: 16px; padding-top: 0px\">复制地址</span></a></li>\r\n				<li id=\"footerModifyInfoArea\" style=\"padding-bottom: 0px; list-style-type: none; margin: 0px; padding-left: 0px; padding-right: 0px; float: left; height: 23px; list-style-image: none; padding-top: 0px\">\r\n					<a class=\"c_tx drop_list\" href=\"javascript:void(0)\" id=\"footerModifyInfoAreaBtn\" onclick=\"return false;\" style=\"position: relative; padding-bottom: 5px; line-height: 16px; margin: 0px; padding-left: 10px; padding-right: 30px; display: inline-block; height: 16px; color: rgb(38,112,154); cursor: pointer; text-decoration: none; padding-top: 2px\"><span class=\"adjust\" style=\"padding-bottom: 0px; line-height: 16px; margin: 0px; padding-left: 0px; padding-right: 0px; float: left; height: 16px; padding-top: 0px\">编辑</span></a></li>\r\n			</ul>\r\n		</div>\r\n		<div class=\"mod_links\" style=\"padding-bottom: 0px; margin: 6px 0px 8px; padding-left: 0px; padding-right: 0px; float: right; padding-top: 0px\">\r\n			<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a class=\"c_tx\" href=\"http://user.qzone.qq.com/1098939153/blog/1337401351\" id=\"navigatorSpan4\" rel=\"prevBlog\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; display: inline-block; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" title=\"【转】袁腾飞说文革语录\">上一篇</a></span><span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><a class=\"c_tx\" href=\"http://user.qzone.qq.com/1098939153/blog/1337170010\" id=\"navigatorSpan2\" rel=\"nextBlog\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; display: inline-block; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" title=\"查看文章\">下一篇：查看文章</a></span></div>\r\n	</div>\r\n</div>\r\n<p>\r\n	&nbsp;</p>\r\n', '0', '1', '1', '2016-09-28 09:33:11', null, '0');
INSERT INTO `entry` VALUES ('314', '76', '查看文章 2012-5-16 20:06 阅读(0)', '<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	这个问题在很多书上都是有的，算法本身比较简单，但是其内在的原理和思想没见过几个人细说的，在这里我稍微说一下，算是一点原创的想法吧。直观的想法就是我们把所有连续子序列和找出来，之后把其中最大的拿出就成了，可是这样做显然是不经济的。仔细思考一下问题就会发现这个问题本身有很强的特点。由于子串连续性，我们的最大子串的出现是有条件的，那么这条件是什么呢？考虑如下的子序列，</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&nbsp;&nbsp;&nbsp;&nbsp; a1a2...ai-1ai&nbsp;&nbsp;&nbsp;&nbsp;</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	它的最大子序列是</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&nbsp;&nbsp;&nbsp; akak+1...ak+m-1ak+m&nbsp;&nbsp;&nbsp;&nbsp;</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	而如果原子序列右端再加入一新的元素时，新的最大子序列只可能是或是从最新的右端向左数最大的连续子序列，因此我们要做的只是计录现在序列的最大子序列值和紧挨右端的最大子序列值，注意我们的子序列可以为空，因此哪果子序列的值为负，我们就可以把它丢弃，用0做最大子序列值。因此维护一个最大右端子序列值是十分容易的，如果它是负的就舍弃它，从下一个开始计数，如果是正就留着它，同时如果它比先前存储的原最大连续子序列值大的话就把最大值设为当前的最大连续最大右端子序列的值，这样只要一次遍历就可以把结果求出。下面是我实现的代码，仅供参考.</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">unsigned<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: blue; padding-top: 0px\">int<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">foo</span>(<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: blue; padding-top: 0px\">int</span>*<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">azz</span>,<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: blue; padding-top: 0px\">int<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">len</span>)</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">{</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: blue; padding-top: 0px\">int</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\"><span class=\"Apple-converted-space\">&nbsp;</span>ThisSum</span>=<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: red; padding-top: 0px\">0</span>,<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">j</span>=<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: red; padding-top: 0px\">0</span>;</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: blue; padding-top: 0px\">unsigned</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: blue; padding-top: 0px\"><span class=\"Apple-converted-space\">&nbsp;</span>int<span class=\"Apple-converted-space\">&nbsp;</span></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">MaxSum</span>=<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: red; padding-top: 0px\">0</span>;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: blue; padding-top: 0px\">for</span>(<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">j</span><span class=\"Apple-converted-space\">&nbsp;</span>=<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: red; padding-top: 0px\">0</span>;<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">j</span><span class=\"Apple-converted-space\">&nbsp;</span>&lt;<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">len</span>;<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">j</span>++ )</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>{</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">ThisSum</span><span class=\"Apple-converted-space\">&nbsp;</span>+=<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">azz</span>[<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">j</span><span class=\"Apple-converted-space\">&nbsp;</span>];</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: blue; padding-top: 0px\">if</span>(<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">ThisSum</span><span class=\"Apple-converted-space\">&nbsp;</span>&gt; (<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: blue; padding-top: 0px\">int</span>)<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">MaxSum</span><span class=\"Apple-converted-space\">&nbsp;</span>)</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">MaxSum</span><span class=\"Apple-converted-space\">&nbsp;</span>=<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">ThisSum</span>;</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: blue; padding-top: 0px\">else</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: blue; padding-top: 0px\">if</span>(<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">ThisSum</span><span class=\"Apple-converted-space\">&nbsp;</span>&lt;<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: red; padding-top: 0px\">0</span><span class=\"Apple-converted-space\">&nbsp;</span>)</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\">ThisSum</span><span class=\"Apple-converted-space\">&nbsp;</span>=<span class=\"Apple-converted-space\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: red; padding-top: 0px\">0</span>;</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>}</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: blue; padding-top: 0px\">return</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(1,0,1); padding-top: 0px\"><span class=\"Apple-converted-space\">&nbsp;</span>MaxSum</span>;</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">}</span></p>\r\n', '0', '1', '1', '2016-09-28 09:33:30', null, '0');
INSERT INTO `entry` VALUES ('315', '76', '【动态规划】最大连续序列和最大子矩阵 2012-5-16 19:59 阅读(0)', '<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	一开始接触的动态规划题目就是在杭电OJ上的1003 Max Sum，求一个数列的最大连续子序列，当时花了好长时间才弄懂。后来接触到更多的动态规划题目，就愈发头晕了。</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	Max Sum 这题应该是很基础吧,状态转移方程为：DP[i]=Max{num[i],DP[i-1]+num[i]} 其中DP[i]表示的是以i位置结束的最大连续子序列的和。如果DP[i-1]&lt;0，也就是说 DP[i-1]+num[i]&lt;num[i],那么最大的序列和就更新为num[i]。具体的代码如下：</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&nbsp;</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&nbsp;</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	#include&lt;iostream&gt;<br />\r\n	&nbsp;#include&lt;cstdio&gt;<br />\r\n	&nbsp; using namespace std;<br />\r\n	&nbsp; int main()<br />\r\n	&nbsp;{<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp; int t,n;<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp; int i,j;<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp; int start,end,p,max,num,sum;<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp; scanf(&quot;%d&quot;,&amp;t);<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp; for(i=1;i&lt;=t;i++)<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp; {<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; p=1;sum=0;<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; max=INT_MIN;<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; scanf(&quot;%d&quot;,&amp;n);<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; for(j=1;j&lt;=n;j++)<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; scanf(&quot;%d&quot;,&amp;num);<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; sum+=num;<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if(sum&gt;max)<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; max=sum;<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; start=p;<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; end=j;<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if(sum&lt;0)<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; p=j+1;<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; sum=0;<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; printf(&quot;Case %d:\\n&quot;,i);<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; printf(&quot;%d %d %d\\n&quot;,max,start,end);<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if(i!=t)<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; printf(&quot;\\n&quot;);<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp; }<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp; return 0;<br />\r\n	&nbsp;}</p>\r\n', '0', '1', '1', '2016-09-28 09:33:48', null, '0');
INSERT INTO `entry` VALUES ('316', '76', '动态规划法-------最大连续子序列和 2012-5-16 19:51 阅读(0)', '<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	动态规划法解决最大连续子序列和</p>\r\n<h2 style=\"padding-bottom: 0px; line-height: 22px; widows: 1; text-transform: none; background-color: rgb(255,255,255); font-variant: normal; font-style: normal; text-indent: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-family: punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); font-size: 14px; word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;问题描述 ：<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 数组 int a[] = {-4 , 3 ,56 , -15 , 34 , 0 , -14 , 4} ; 某几个连续的子序列其和最大，比如a0+a1 = -1 。a1+a2+a3+a4 = 78 。则a1 a2 a3a4组成的数组即是所求。<br />\r\n	&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;</h2>\r\n<h2 style=\"padding-bottom: 0px; line-height: 22px; widows: 1; text-transform: none; background-color: rgb(255,255,255); font-variant: normal; font-style: normal; text-indent: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-family: punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); font-size: 14px; word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp; 解决方法：<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 此题尝试使用动态规划的方法进行解决，首先建立状态方程。<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 设b[j]表示第j处，以a[j] 结尾的子序列的最大和。<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 则b[j] = max(a[j] + b[j-1] , a[j]) ，而我们的所求的答案，就是从1- n对b数组求最大值。<br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp;</h2>\r\n<h2 style=\"padding-bottom: 0px; line-height: 22px; widows: 1; text-transform: none; background-color: rgb(255,255,255); font-variant: normal; font-style: normal; text-indent: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-family: punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); font-size: 14px; word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&nbsp;代码如下：<span class=\"Apple-converted-space\">&nbsp;</span><br />\r\n	&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;</h2>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&nbsp;&nbsp;</p>\r\n<div style=\"border-bottom: rgb(204,204,204) 1px solid; border-left: rgb(204,204,204) 1px solid; padding-bottom: 4px; widows: 1; text-transform: none; background-color: rgb(238,238,238); font-variant: normal; font-style: normal; text-indent: 0px; margin: 0px; padding-left: 4px; width: 862px; padding-right: 5px; font-family: punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); font-size: 13px; word-break: break-all; border-top: rgb(204,204,204) 1px solid; font-weight: normal; border-right: rgb(204,204,204) 1px solid; word-spacing: 0px; padding-top: 4px; -webkit-text-stroke-width: 0px\">\r\n	<img align=\"top\" data-=\"\" data-img-idx=\"0\" src=\"http://qqadapt.qpic.cn/adapt/0/2f88ce13-0b65-4eb5-dc67-88e02dbcfc90/800?pt=0&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /><img align=\"top\" data-=\"\" data-img-idx=\"1\" src=\"http://qqadapt.qpic.cn/adapt/0/dbf989d5-7862-6817-39b6-42d8621fe1f0/800?pt=0&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /><span style=\"border-bottom: rgb(128,128,128) 1px solid; border-left: rgb(128,128,128) 1px solid; padding-bottom: 0px; background-color: rgb(255,255,255); margin: 0px; padding-left: 0px; padding-right: 0px; border-top: rgb(128,128,128) 1px solid; border-right: rgb(128,128,128) 1px solid; padding-top: 0px\">/**/</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,128,0); padding-top: 0px\">/*</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,128,0); padding-top: 0px\"><img align=\"top\" data-=\"\" data-img-idx=\"2\" src=\"http://qqadapt.qpic.cn/adapt/0/df37983f-39da-a189-b8c8-14e01a6a9011/800?pt=0&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" />&nbsp;最大连续字段和&nbsp;时间复杂度为O(N)&nbsp;<br />\r\n	<img align=\"top\" data-=\"\" data-img-idx=\"3\" src=\"http://qqadapt.qpic.cn/adapt/0/df37983f-39da-a189-b8c8-14e01a6a9011/800?pt=0&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" />&nbsp;定义b[j]为数组中包含a[j]的最大连续子序列和<br />\r\n	<img align=\"top\" data-=\"\" data-img-idx=\"4\" src=\"http://qqadapt.qpic.cn/adapt/0/df37983f-39da-a189-b8c8-14e01a6a9011/800?pt=0&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" />&nbsp;注意一个误区，b[j]&nbsp;并不是1-j中最大的连续子序列的和，只是包含a[j]的最大子序列的和&nbsp;<br />\r\n	<img align=\"top\" data-=\"\" data-img-idx=\"5\" src=\"http://qqadapt.qpic.cn/adapt/0/df37983f-39da-a189-b8c8-14e01a6a9011/800?pt=0&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" />&nbsp;而我们所要求的是求出b[j]中最大的值，即为所求&nbsp;<br />\r\n	<img align=\"top\" data-=\"\" data-img-idx=\"6\" src=\"http://qqadapt.qpic.cn/adapt/0/df37983f-39da-a189-b8c8-14e01a6a9011/800?pt=0&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /><br />\r\n	<img align=\"top\" data-=\"\" data-img-idx=\"7\" src=\"http://qqadapt.qpic.cn/adapt/0/df37983f-39da-a189-b8c8-14e01a6a9011/800?pt=0&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" />&nbsp;状态方程为:&nbsp;b[j]&nbsp;=&nbsp;max(b[j-1]&nbsp;+&nbsp;a[j]&nbsp;,&nbsp;a[j])&nbsp;<br />\r\n	<img align=\"top\" data-=\"\" data-img-idx=\"8\" src=\"http://qqadapt.qpic.cn/adapt/0/0ac3a2d5-3663-ec01-c7f7-225264eeefae/800?pt=0&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" /></span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,128,0); padding-top: 0px\">*/</span></span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); padding-top: 0px\"><img align=\"top\" data-=\"\" data-img-idx=\"9\" src=\"http://qqadapt.qpic.cn/adapt/0/cbef093d-cc04-4b27-9383-2001e2365e43/800?pt=0&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" />#include&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); padding-top: 0px\">&lt;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); padding-top: 0px\">iostream</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); padding-top: 0px\">&gt;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); padding-top: 0px\"><img align=\"top\" data-=\"\" data-img-idx=\"10\" src=\"http://qqadapt.qpic.cn/adapt/0/cbef093d-cc04-4b27-9383-2001e2365e43/800?pt=0&amp;ek=1&amp;kp=1&amp;sce=0-12-12\" style=\"border-bottom: 0px; border-left: 0px; padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; vertical-align: top; border-top: 0px; border-right: 0px; padding-top: 0px\" />&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,255); padding-top: 0px\">using</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); padding-top: 0px\">&nbsp;</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,255); padding-top: 0px\">namespace</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(0,0,0); padding-top: 0px\">&nbsp;std&nbsp;;<br />\r\n	<img align=\