INSERT INTO `entry` VALUES ('317', '76', '编程珠玑第8章：算法设计 2012-5-16 16:47 阅读(0)', '<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">输入是一个具有N个浮点数字的向量X: 其输出是在输入的任何相邻子向量中找出的最大和。</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">例如，输入如下10个元素：</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">31 －41 59 26 －53 58 97 －93 －23 84</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">返回 x[2..6]的总和，或为187</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">&nbsp;</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; background-color: rgb(255,0,0); margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">算法一：O(n^3)的算法</span></strong><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">int max1(int* x, int* start, int* end){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; int maxsofar = 0, mi, mj, sum = 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; int i, j, k;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; for(i = 0; i &lt; N; i++){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; for(j = i; j &lt; N; j ++){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; sum = 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; for(k = i; k &lt;= j; k ++){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; sum += x[k];</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if(sum &gt; maxsofar){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; maxsofar = sum;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; mi = i;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; mj = j;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; *start = mi;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; *end = mj;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; return maxsofar;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">}</span><br />\r\n	<br />\r\n	<strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; background-color: rgb(255,0,0); margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">算法二：O(n^2)的两个算法</span></strong><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">int max2(int* x, int* start, int* end){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; int maxsofar = 0, mi, mj, sum = 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; int i, j;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; for(i = 0; i &lt; N; i++){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; sum = 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; for(j = i; j &lt; N; j ++){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; sum += x[j];</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if(sum &gt; maxsofar){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; maxsofar = sum;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; mi = i;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; mj = j;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; *start = mi;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; *end = mj;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; return maxsofar;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">}</span><br />\r\n	<br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">int max3(int* x, int* start, int* end){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; int cumarr[N + 1], maxsofar = 0;//避免访问cumarr[-1]</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; int i, j, mi, mj, sum;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; cumarr[0] = 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; for(i = 0; i &lt; N; i ++){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; cumarr[i + 1] = cumarr[i] + x[i];</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; for(i = 0; i &lt; N; i++){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; for(j = i; j &lt; N; j ++){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; sum = cumarr[j + 1] - cumarr[i];</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; if(sum &gt; maxsofar){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; maxsofar = sum;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; mi = i;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; mj = j;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; *start = mi;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; *end = mj;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; return maxsofar;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">}</span><br />\r\n	<br />\r\n	<strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; background-color: rgb(255,0,0); margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">算法三、分治算法，复杂度O(nlogn)Michael Shamos一个通宵</span></strong><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">将大小为n的问题划分为两个规模近似为N/2的字问题。最大和的向量或者在左半部，或者在右半部，或者跨越中间分界线。如果用T(n)表示解决规模为n的问题所花的时间，那么T(1)=O(n)且T(n) = 2T(n/2)+O(n)。</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">int max4(int* x, int start, int end){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; if(start &gt; end)</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; return 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; if(start == end){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; if(x[start] &lt;= 0)</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; return 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; else</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; return x[start];</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; int m = ( start + end )/2;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; int i;</span><br />\r\n	<br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; int lmax = 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; int sum = 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; for(i = m; i &gt;= 0; i --){//最大左序列已m结束</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; sum += x[i];</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; if(sum &gt; lmax)</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; lmax = sum;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; int rmax = 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; sum = 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; for(i = m + 1; i &lt;= end; i++){//最大右序列从m+1开始</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; sum += x[i];</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; if(sum &gt; rmax)</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; rmax = sum;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;//max(lmax+rmax, max4(1,m), max4(m+1,u))</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; int ret = 0, tmp = 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; tmp = lmax + rmax;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; if(tmp &gt; ret)</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; ret = tmp;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; tmp = max4(x, 0, m);</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; if(tmp &gt; ret)</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; ret = tmp;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; tmp = max4(x, m+1, end);</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; if(tmp &gt; ret)</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; ret = tmp;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp; return ret;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">}</span><br />\r\n	<br />\r\n	<strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; background-color: rgb(255,0,0); margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">算法四、扫描算法：线性算法（动态规划）。Jay Kadane不出几分钟给出提纲</span></strong></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<b style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">从最左端一直扫描到最右端，记下碰到过的最大总和子向量。假设解决了X[0...i-1]的问题，考虑第i个值,最大和子数组要么在i-1个元素中（存储在maxsofar中）要么截止到第i个</span></b><b style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">(存储在maxendinghere中)</span></b><b style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">。若</span></b><b style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">maxendinghere&lt;0,从下个数开始重新计算一个新的子数组。</span></b></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">int max5(int* x){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; int maxsofar = 0, maxendinghere = 0;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; int i;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; for(i = 0; i &lt; N; i++){</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if(maxendinghere + x[i] &gt; 0)//</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; maxendinghere = maxendinghere + x[i];</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;else &nbsp; &nbsp;maxendinghere = 0; &nbsp; &nbsp;</span></span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if(maxendinghere &gt; maxsofar)</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; maxsofar = maxendinghere;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; return maxsofar;</span><br />\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">}</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; background-color: rgb(255,0,0); margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">算法设计技术：</span></strong></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">保存状态</span></strong><span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">：避免重复计算，算法2和扫描算法。</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">将信息预处理到数据结构中：算法2b中cumarr结构允许对子向量中的总和进行快速计算。</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">分治算法</span></strong><span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">：不太懂递归，哎</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">扫描算法</span></strong><span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">：有关数组的问题经常想到</span><span style=\"padding-bottom: 0px; background-color: rgb(255,169,0); margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">将X[0...n-1]的问题扩展到X[0...n]。扫描算法同时保存旧的答案以计算新答案。</span></span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">累计</span></strong><span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">：累计表中，第i个元素包含x中前i个值的总和，处理范围时，这一类表很常见。</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">eg.假如要找出&nbsp;和&nbsp;最接近0的子向量：初始化累加向量cum[i],如果cum[i-1]=cum[u],那么子向量和就接近于0.因此可以通过排序cum数组定位两个最接近的元素找到和接近于0的子向量。</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<strong style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\"><span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">下限</span></strong><span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">：证明&quot;算法已经是可能算法中最佳&quot;</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">&lt;Data Structures and Algorithms&gt;第10章 算法设计技术</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">&lt;Introduction to Algorithms&gt;高级设计与分析部分</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; line-height: 20px; background-color: rgb(255,169,0); margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">&quot;只有经过广泛的研究和实践，你才能熟练的使用算法设计技术；大多数程序员只是从有关算法方面的课程或教科书中获得这些知识&rdquo;</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&nbsp;</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">最大子矩阵和</span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; line-height: 20px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\"><a href=\"http://blog.csdn.net/jeiwt/archive/2010/05/06/5561773.aspx\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">http://blog.csdn.net/jeiwt/archive/2010/05/06/5561773.aspx</span></a></span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<a href=\"http://blog.csdn.net/hongjiqin/archive/2006/07/14/921337.aspx\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">http://blog.csdn.net/hongjiqin/archive/2006/07/14/921337.aspx</span></a></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\"><a href=\"http://cid-5ea3a401c08a0475.spaces.live.com/Blog/cns!5EA3A401C08A0475!139.entry\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">http://cid-5ea3a401c08a0475.spaces.live.com/Blog/cns!5EA3A401C08A0475!139.entry</span></a></span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<a href=\"http://hi.baidu.com/yangguangli/blog/item/a5c128823e656396f703a626.html\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\">http://hi.baidu.com/yangguangli/blog/item/a5c128823e656396f703a626.html</span></a></p>\r\n<p>\r\n	<br class=\"Apple-interchange-newline\" />\r\n	&nbsp;</p>\r\n', '0', '1', '1', '2016-09-28 09:34:24', null, '0');
INSERT INTO `entry` VALUES ('318', '76', '最大子串和问题（Maximum Subarray）【转】 2012-5-16 16:46 阅读(0)', '<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">又一个经典问题，对于一个包含负值的数字串array[1...n]，要找到他的一个子串array[i...j]（0&lt;=i&lt;=j&lt;=n），使得在array的所有子串中，array[i...j]的和最大。</span></span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">这里我们需要注意子串和子序列之间的区别。子串是指数组中连续的若干个元素，而子序列只要求各元素的顺序与其在数组中一致，而没有连续的要求。对于一个元素数为n的数组，其含有2^n个子序列和n(n+1)/2个子串。如果使用穷举法，则至少需要O(n^2)的时间才能得到答案。卡耐基梅隆大学的Jay Kadane</span><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">的给出了一个线性时间算法，我们就来看看，如何在线性时间内解决最大子串和问题。</span></span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">要说明Kadane算法的正确性，需要两个结论。首先，对于array[1...n]，如果array[i...j]就是满足和最大的子串，那么对于任何k(i&lt;=k&lt;=j)，我们有array[i...k]的和大于0。因为如果存在k使得array[i...k]的和小于0，那么我们就有array[k+1...j]的和大于array[i...j]，这与我们假设的array[i...j]就是array中和最大子串矛盾。</span></span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">其次，我们可以将数组从左到右分割为若干子串，使得除了最后一个子串之外，其余子串的各元素之和小于0，且对于所有子串array[i...j]和任意k（i&lt;=k&lt;j），有array[i...k]的和大于0。此时我们要说明的是，满足条件的和最大子串，只能是上述某个子串的前缀，而不可能跨越多个子串。我们假设array[p...q]，是array的和最大子串，且array[p...q]，跨越了array[i...j]，array[j+1...k]。根据我们的分组方式，存在i&lt;=m&lt;j使得array[i...m]的和是array[i...j]中的最大值，存在j+1&lt;=n&lt;k使得array[j+1...n]的和是array[j+1...k]的最大值。由于array[m+1...j]使得array[i...j]的和小于0。此时我们可以比较array[i...m]和array[j+1...n]，如果array[i...m]的和大于array[j+1...n]则array[i...m]&gt;array[p...q]，否array[j+1...n]&gt;array[p...q]，无论谁大，我们都可以找到比array[p...q]和更大的子串，这与我们的假设矛盾，所以满足条件的array[p...q]不可能跨越两个子串。对于跨越更多子串的情况，由于各子串的和均为负值，所以同样可以证明存在和更大的非跨越子串的存在。对于单元素和最大的特例，该结论也适用。</span></span></p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	<span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; font-size: 16px; padding-top: 0px\"><span style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; padding-top: 0px\">根据上述结论，我们就得到了Kadane算法的执行流程，从头到尾遍历目标数组，将数组分割为满足上述条件的子串，同时得到各子串的最大前缀和，然后比较各子串的最大前缀和，得到最终答案。我们以array={?2, 1, ?3, 4, ?1, 2, 1, ?5, 4}为例，来简单说明一下算法步骤。通过遍历，可以将数组分割为如下3个子串（-2），（1，-3），（4，-1，2，1，-5，4），这里对于（-2）这样的情况，单独分为一组。各子串的最大前缀和为-2，1，6，所以目标串的最大子串和为6。</span></span></p>\r\n', '0', '1', '1', '2016-09-28 09:34:41', null, '0');
INSERT INTO `entry` VALUES ('319', '76', '自由女神 2012-5-6 13:48 阅读(0)', '<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&ldquo;让那些因为渴望呼吸到自由空气，而历经长途跋涉业已疲惫不堪，身无分文的人们，相互依偎着投入我的怀抱吧！我站在金门口，高举自由的灯火。&rdquo;</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&nbsp;</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&nbsp;</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	自由女神穿着<a href=\"http://baike.baidu.com/view/64778.htm\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font color=\"#136ec2\">古希腊</font></a>风格的服装（一说<a href=\"http://baike.baidu.com/view/2245.htm\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font color=\"#136ec2\">罗马</font></a>古代长袍），头戴光芒四射的冠冕，七道尖芒象征世界七大洲。自由女神像腰宽10.6米，嘴宽91厘米，右手高举象征自由的火炬，长达12.8米，火炬的边沿上可以站12个人。左手捧着一本封面刻有&ldquo;<a href=\"http://baike.baidu.com/view/1190648.htm\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font color=\"#136ec2\">1776年</font></a><a href=\"http://baike.baidu.com/view/326463.htm\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font color=\"#136ec2\">7月4日</font></a>&rdquo;字样的法律典籍，象征着这一天签署的《<a href=\"http://baike.baidu.com/view/49962.htm\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font color=\"#136ec2\">独立宣言</font></a>》。脚下是打碎的<a href=\"http://baike.baidu.com/view/128187.htm\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font color=\"#136ec2\">手铐</font></a>、<a href=\"http://baike.baidu.com/view/661884.htm\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font color=\"#136ec2\">脚镣</font></a>和<a href=\"http://baike.baidu.com/view/3175190.htm\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font color=\"#136ec2\">锁链</font></a>，象征着挣脱暴政的约束和自由.而其体态又似一位古希腊美女，使人感到亲切自然。当夜幕降临，神像基座的灯光向上照射，将女神照得宛如一座淡青色的玉雕。</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&nbsp;</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	&nbsp;</p>\r\n<p style=\"padding-bottom: 0px; widows: 1; text-transform: none; background-color: rgb(255,255,255); text-indent: 0px; margin: 0px 0px 0.7em; padding-left: 0px; padding-right: 0px; font: 14px/22px punctuation, 微软雅黑, Tohoma; white-space: normal; letter-spacing: normal; color: rgb(68,68,68); word-spacing: 0px; padding-top: 0px; -webkit-text-stroke-width: 0px\">\r\n	1851年<a href=\"http://baike.baidu.com/view/843557.htm\" style=\"padding-bottom: 0px; margin: 0px; padding-left: 0px; padding-right: 0px; color: rgb(38,112,154); text-decoration: none; padding-top: 0px\" target=\"_blank\"><font color=\"#136ec2\">路易&middot;拿破仑&middot;波拿巴</font></a>发动政变推翻第二共和国后的一天，一群坚定的共和党人在街头筑起防御工事，暮色苍茫时，一个年轻姑娘手持熊熊燃烧的火炬，跃过障碍物，高呼&ldquo;前进&rdquo;的口号向敌人冲去，波拿巴分子的枪声响了，姑娘倒在血泊中。巴托尔迪耳闻这一事实，心情久久不能平静。从此这位高攀火炬的勇敢姑娘就成为他心中自由的象征。</p>\r\n', '0', '1', '1', '2016-09-28 09:34:58', null, '0');
