;*.png&quot;,        file_types_description : &quot;Image File&quot;,        file_size_limit : &quot;10 MB&quot;,        file_queue_limit : &quot;1&quot;,            // Event handler settings        file_dialog_start_handler: fileDialogStart, // fired after selectFile is called.        file_queued_handler : fileQueued,           // fired after file selection dialog close.        file_queue_error_handler : fileQueueError,  // fired when file was not queued.        file_dialog_complete_handler : fileDialogComplete,// fired when all files queued.                         upload_progress_handler : uploadProgress,  // upload status        upload_error_handler : uploadError,        // fired when upload error thrown        upload_success_handler : uploadSuccess,    // fired when server return a 200 status        upload_complete_handler : uploadComplete,  // fired at the end of an upload cycle            // Button Settings        button_image_url : &quot;&lt;%=contextPath%&gt;/image/btnUpload.png&quot;,        button_placeholder_id : &quot;btnPlaceHolder&quot;,        button_width: 61,        button_height: 22,        button_action: SWFUpload.BUTTON_ACTION.SELECT_FILE, // 单选        // debug infor        debug:false    });};    &lt;/script&gt;&lt;/head&gt;&lt;body&gt;&lt;div id=&quot;uploadContent&quot;&gt;    &lt;input id=&quot;txtFileName&quot; type=&quot;text&quot; disabled=&quot;disabled&quot; value=&quot;&quot; style=&quot;width:151px;&quot;/&gt;    &lt;span id=&quot;btnPlaceHolder&quot;&gt;&lt;/span&gt;    &lt;div id=&quot;uploadProgress&quot;&gt;        &lt;div id=&quot;colorStatus&quot;&gt;&lt;/div&gt;        &lt;div id=&quot;percentTxt&quot;&gt;&lt;/div&gt;    &lt;/div&gt;&lt;/div&gt;&lt;input id=&quot;btnStartUpload&quot; type=&quot;button&quot; value=&quot;开始上传&quot; onclick=&quot;startUpload()&quot; disabled=&quot;disabled&quot; style=&quot;position:relative;left:200px;&quot;/&gt;&lt;/body&gt;&lt;/html&gt;</pre>\r\n	<p style=\"padding-bottom: 0px; margin: 1em 0px;